insert into pops (clinic_id, numero, titulo, estrutura) values
  ((select id from clinics order by created_at limit 1), '001/2026', 'Ácido Tricloroacético (ATA) 90% na onicofose e fungos', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>nº_________ ÁCIDO TRICLOROACÉTICO (ATA) A 90% NO TRATAMENTO DE ONICOFOSE E FUNGOS</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação do ATA 90% no tratamento de onicofose e fungos. O uso de Ácido Tricloroacético (ATA) a 90% no tratamento de onicofose (calosidade no leito ungueal) e fungos nas unhas é uma técnica utilizada por podólogos para remover lesões e desinfetar a área afetada. Este procedimento deve ser realizado com cuidado, pois o ATA é uma substância cáustica e pode causar queimaduras se não for aplicado corretamente</p>"}]}, {"id": "b3", "subtitulo": "EXECUTANTE", "linhas": [{"col1": "", "col2": "<p>Profissional Enfermeira Estéta</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>1. Onicofose (Hiperceratose Subungueal):</p><ul><li>Presença de calosidades ou espessamentos sob a unha, geralmente devido a trauma repetitivo ou pressão.</li><li>Dificuldade em cortar as unhas devido à espessura aumentada causada por onicofose. 2. Onicomicose (Infecção Fúngica das Unhas):</li><li>Diagnóstico confirmado de infecção fúngica nas unhas (onicomicose), especialmente quando outras formas de tratamento (tópicas ou orais) não foram eficazes.</li><li>Alterações na coloração, espessura e forma das unhas devido à infecção fúngica.</li><li>Casos de onicomicose superficial branca onde o fungo está presente apenas na superfície da unha. 3. Remoção de Lesões Hiperceratósicas:</li><li>Necessidade de remover áreas de hiperceratose (espessamento) associadas a condições como psoríase ungueal. 4. Desbridamento de Tecidos Danificados:</li><li>Necessidade de desbridamento químico para remover tecido necrosado ou infectado na área subungueal</li></ul>"}]}, {"id": "b5", "subtitulo": "PRINCIPAIS CONTRAINDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>1. Alergia ao Ácido Tricloroacético: História conhecida de reação alérgica ao ácido tricloroacético ou a componentes do tratamento. 2. Pele Sensível ou Danificada: Presença de pele sensível, inflamada, ferida ou ulcerada ao redor da área a ser tratada. nº_________ ÁCIDO TRICLOROACÉTICO (ATA) A 90% NO TRATAMENTO DE ONICOFOSE E FUNGOS</p><ul><li>Pacientes com condições dermatológicas que afetam a integridade da pele, como eczema ou dermatite. 3. Doenças Sistêmicas Graves: Pacientes com doenças sistêmicas graves que afetam a cicatrização, como diabetes não controlada ou doenças vasculares periféricas. 4. Gravidez e Lactação: O uso de ATA em altas concentrações durante a gravidez e lactação deve ser evitado devido à falta de estudos de segurança. 5. Comprometimento da Imunidade: Pacientes imunocomprometidos, como aqueles em tratamento com imunossupressores ou com doenças que afetam o sistema imunológico, como HIV/AIDS. 6. Uso em Crianças: Deve ser evitado em crianças pequenas devido ao risco aumentado de complicações e dificuldades em manejar o desconforto e a dor. 7. História de Queloides: Pacientes com tendência a desenvolver cicatrizes queloides devem evitar este tratamento devido ao risco de cicatrização excessiva. CONSIDERAÇÕES ADICIONAIS: Sensibilidade ao Procedimento:</li><li>O paciente deve ser informado sobre o potencial de desconforto ou dor durante e após a aplicação do ácido.</li><li>Devem ser seguidas estritamente as orientações de pós-tratamento, incluindo evitar trauma na área tratada e manter a área limpa e seca. Supervisão Profissional:</li><li>O procedimento deve ser realizado por um profissional qualificado e experiente para minimizar o risco de complicações.</li><li>Monitoramento contínuo após o tratamento é essencial para avaliar a resposta e detectar qualquer sinal de complicação precoce</li></ul>"}]}, {"id": "b6", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, máscara Profissional – Luvas, óculos de proteção, touca, jaleco e máscara</p>"}]}, {"id": "b7", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<ul><li>Ácido Tricloroacético (ATA) 90%</li><li>Água estéril ou solução salina nº_________ ÁCIDO TRICLOROACÉTICO (ATA) A 90% NO TRATAMENTO DE ONICOFOSE E FUNGOS</li><li>Algodão ou aplicadores de ponta de algodão</li><li>Pinça e espátula de podologia esterilizadas</li><li>Gaze esterilizada</li><li>Creme ou pomada emoliente (opcional, para uso pós-procedimento)</li><li>Água corrente ou chuveiro portátil (para emergência)</li></ul>"}]}, {"id": "b8", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Protocolo</p>", "col2": "<p>Anamnese - Consulta Inicial: a. Realize uma consulta inicial para avaliar a condição das unhas e confirmar o diagnóstico de onicofose ou infecção fúngica. b. Explique o procedimento ao paciente, incluindo os possíveis riscos e benefícios. - Protocolo: ii. Antes de cada atendimento deve-se desinfetar a alça do refletor, borrifador, bancada, puxador da gaveta, braços e alavancas da cadeira, etc iii. Desinfecção da maca com álcool 70% entre cada cliente iv. Maca com lençol de papel descartável v. Higienização das mãos (ver Manual de Rotinas e Procedimentos) vi. Acomodar o cliente na maca durante todo o procedimento vii. Limpar a área ao redor das unhas com uma solução antisséptica. viii. Se necessário, remover qualquer esmalte ou produtos cosméticos das unhas. ix. Aplicação do ATA: a. Utilizando um aplicador de ponta de algodão, molhe-o com o ácido tricloroacético a 90%. b. Com cuidado, aplique o ATA diretamente na área afetada pela onicofose ou fungo. Evite contato com a pele ao redor. c. Deixe o ácido agir por alguns minutos (geralmente 3-5 minutos), observando a reação da pele e da unha. A área tratada pode começar a esbranquiçar e formar uma crosta. d. Caso o paciente sinta desconforto intenso, interrompa a aplicação e lave a área imediatamente com água corrente. x. Neutralização e Remoção: a. Após o tempo de ação, remova o excesso de ácido com uma gaze esterilizada. nº_________ ÁCIDO TRICLOROACÉTICO (ATA) A 90% NO TRATAMENTO DE ONICOFOSE E FUNGOS b. Lave a área tratada com água estéril ou solução salina para neutralizar o efeito do ácido. xi. Pós-Tratamento: a. Aplique uma pomada ou creme emoliente na área ao redor das unhas, se necessário, para reduzir irritação. b. Oriente o paciente sobre os cuidados pós-procedimento, como evitar traumatismos na área tratada e manter a área limpa e seca. c. Agende uma consulta de acompanhamento para avaliar a eficácia do tratamento e realizar outras aplicações, se necessário</p>"}]}, {"id": "b9", "subtitulo": "ATENÇÃO", "linhas": [{"col1": "", "col2": "<p>Tenha água corrente disponível para neutralizar o ácido rapidamente em caso de aplicação excessiva ou contato indesejado com a pele</p>"}, {"col1": "<p>B. Pós-procedimento</p>", "col2": "<p>a. Informe o paciente sobre possíveis complicações, como dor, queimaduras ou infecção secundária, e como proceder em caso de emergência. b. Registre o procedimento realizado e o nº do lote dos produtos utilizados na Ficha do Cliente. c. Faça o acompanhamento do paciente para monitorar a cicatrização e a eficácia do tratamento. Pode ser necessário mais de uma aplicação dependendo da gravidade da onicofose ou da infecção fúngica</p>"}, {"col1": "<p>C. Referências</p>", "col2": "<p>Literárias Mônica Cristina de Oliveira et al. Podología Integral: Abordagem Clínica, Laboratorial e Radiológica (livro). Cristina Oliveira, Fernando Marques e Nuno Correia. Podologia e Terapia Complementar: A Nova Visão em Medicina e Saúde (livro). Marta Maria M. C. S. Pimenta. Manual de Tratamento de Calosidades e Calos (livro). Arsenio Veiga de Barros. Tratado de Podologia (livro)</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '002/2026', 'Alta Frequência', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>ALTA FREQUÊNCIA</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação do procedimento de alta frequência. Consiste na utilização de eletrodos de vidro ligados a uma corrente de freqüência alta que produzem efeitos térmicos, vasodilatadores, bactericidas, fungicidas e oxigenantes</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Bactericida / bacteriostático Fungicida Desinfecção do couro cabeludo Estímulo à circulação (alopecia)</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Uso de aparelhos eletromagnéticos como marca-passo cardíaco Gestação Pacientes com distúrbios de sensibilidade Em peles com cosmético inflamável (álcool)</p>"}]}, {"id": "b5", "subtitulo": "TEMPO DE APLICAÇÃO", "linhas": [{"col1": "", "col2": "<p>Varia de acordo com o tratamento escolhido e as orientações de cada fabricante</p>"}]}, {"id": "b6", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente - Touca Profissional – Touca, máscara, jaleco, óculos de proteção e luvas</p>"}]}, {"id": "b7", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Equipamento Eletrodos</p>"}]}, {"id": "b8", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>Avaliação: a. Identificar a área a ser tratada Protocolo: Desinfecção da maca com álcool 70% Maca com lençol de papel descartável Higienização das mãos (ver Manual de Rotinas e Procedimentos) Acomodar o cliente na maca durante todo o procedimento Aplicar a técnica I. Pode ser usado de duas formas após a extração no procedimento de limpeza de pele: a. Faiscamento ou aplicado à distância: o eletrodo não é encostado sobre a pele, ficando distante alguns milímetros e produzindo um faiscamento. Deve-se aplicar por 3 segundos em cada lesão a ser cicatrizada como, por exemplo, sobre pústulas com sangramento após extração. b. Aplicação direta ou efluviação: o eletrodo é encostado sobre a pele gerando efeitos bactericida e fungicida. Deve-se aplicá-lo de 3 a 5 minutos sobre toda a área a ser trabalhada, sendo arrastado suavemente sobre a pele ou aplicado com repetidos movimentos de encostar e afastar o eletrodo sobre a pele, distribuídos por toda a face. ALTA FREQUÊNCIA II. Na terapia capilar , utiliza-se principalmente o eletrodo do tipo bico ou pente que deverá estar em contato direto com o couro cabeludo, utilizando a técnica de aplicação direta (ou efluviação). Durante a aplicação, realizam-se movimentos suaves no couro cabeludo durante todo o tempo de procedimento. O eletrodo do tipo forquilha pode ser utilizado em afecções da barba, como nos casos de foliculites ou pseudofoliculites. O tempo de aplicação varia de 3 a 5 minutos, podendo alcançar até 10 minutos em toda a cabeça. A intensidade utilizada varia de acordo com o conforto do cliente. Após a realização do procedimento, a assepsia do material pode ser realizada com álcool a 70%. B. Cuidados pós-procedimento a. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. b. Anotar na ficha do cliente todos os produtos e equipamentos utilizados nesse procedimento com seus respectivos números de lotes, data de validade e nome do fabricante</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>BORGES, Fábio dos Santos. Dermato - Funcional: modalidades terapêuticas nas disfunções estéticas. São Paulo: Phorte, 2006</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '003/2026', 'Armazenamento Produtos Termolábeis', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>25/10/2026</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever o procedimento correto de armazenamento dos medicamentos termolábeis utilizados no estabelecimento para garantir a sua qualidade, segurança e eficácia, conforme condições de armazenamento estipulados pelos fabricantes dos produtos. São chamados termolábeis os medicamentos particularmente sensíveis à ação da temperatura e que por isso geralmente requerem armazenamento sob refrigeração (entre 2ºC e 8ºC), conforme preconizado no Anexo II da resolução-RDC nº 318/2019 (tabela abaixo): Nas Definições da RDC 430/2020 , em seu Art. 3º, temos: “ XVI – medicamento termolábil: medicamento cuja especificação de temperatura máxima seja igual ou inferior a 8°C”</p>"}]}, {"id": "b3", "subtitulo": "RESPONSABILIDADES", "linhas": [{"col1": "", "col2": "<p>Todos os profissionais devidamente habilitados e capacitados a realizarem procedimentos com medicamentos termolábeis são responsáveis pela qualidade e segurança desses medicamentos, sendo competência do profissional Responsável Técnico assegurar o registro da temperatura do refrigerador do estabelecimento em tabela própria, além de garantir as boas práticas sanitárias no local. REFRIGERADOR: O estabelecimento dispõe de refrigerador EXCLUSIVO para guarda de medicamentos e produtos termolábeis. O refrigerador está devidamente identificado como de uso exclusivo para medicamentos. TERMÔMETRO: O refrigerador EXCLUSIVO para guarda de medicamentos e produtos termolábeis possui termômetro para controle da temperatura. O registro da temperatura é realizado duas vezes ao dia em tabela própria ( ANEXO I )</p>"}]}, {"id": "b4", "subtitulo": "FALTA DE ENERGIA ELÉTRICA / PLANO DE CONTINGÊNCIA", "linhas": [{"col1": "", "col2": "<p>A energia elétrica do estabelecimento é suprida pela concessionária de energia que abastece toda a região. A fim de minimizar o risco de perdas de produtos 25/10/2026 termolábeis por falta de energia, deve ser realizada a transferência dos produtos termolábeis do refrigerador para caixas térmicas de maneira a evitar choques mecânicos e as caixas devem ser apropriadamente identificadas (ex.: produto frágil e produto termolábil), No momento da transferência dos medicamentos termolábeis para caixas térmicas, o responsável deverá realizar inventário, relacionando todos os medicamentos, respectivos lotes e quantidades para, caso seja necessário, transferir a carga para outra unidade interna. O inventário deverá ser preenchido manualmente em formulário próprio impresso, conforme modelo disponível no ANEXO II e deverá ser arquivado, posteriormente, na pasta sanitária do estabelecimento. Caso os produtos termolábeis sejam submetidos a condições de temperaturas inadequadas, ou seja, fora da faixa recomendada (entre 2°C e 8 °C), o Responsável Técnico deverá fazer a segregação e identificação desses produtos para descarte</p>"}]}, {"id": "b5", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>1. refrigerador 2. termômetro que registre a temperatura mínima, máxima e a atual 3. tabela para registro da temperatura</p>"}]}, {"id": "b6", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "", "col2": "<p>A. Procedimento 1. Ao receber o produto termolábil no estabelecimento, o profissional Responsável Técnico deve verificar se o produto encontra-se acondicionado da forma correta (ex. no isopor). 2. Fixar uma lista com o nome dos produtos armazenados dentro do refrigerador para facilitar a identificação e controle (modelo disponível no ANEXO II ). 3. Antes de direcionar o produto novo para o refrigerador, o Responsável Técnico deve realizar a inspeção visual de cada embalagem do produto a fim de garantir as informações abaixo: a. Nome do produto b. Marca c. Lote d. Prazo de validade e. Conteúdo f. País de origem g. Fabricante/importador h. Composição do produto i. Instruções em língua portuguesa j. Autorização de Funcionamento da indústria, na ANVISA; k. Número de registro ou notificação no Ministério da Saúde/ANVISA 4. Armazenar os produtos por número de lote e por prazo de validade. Os produtos com datas de validade mais próximas devem ser estocados à esquerda e na frente, para que sejam usados primeiramente. 5. Manter espaço entre as caixas/frascos dos produtos para permitir a circulação de ar e distância adequada entre as caixas/frascos dos produtos e as paredes do refrigerador. 25/10/2026 6. A temperatura dentro do refrigerador deve estar entre 2ºC a 8ºC. Portanto, deve ser verificada e registrada diariamente em tabela específica (conforme modelo disponível no ANEXO II )</p>"}]}, {"id": "b7", "subtitulo": "OBSERVAÇÃO", "linhas": [{"col1": "", "col2": "<p>Em caso de produtos que precisem ser armazenados abaixo de 2ºC, acondicionar o produto no congelador. 7. Quando se fizer necessária a limpeza ou manutenção do refrigerador, os produtos devem ser transferidos para outro refrigerador ou recipiente que mantenha as mesmas condições exigidas de armazenamento. 8. Em caso de falta de energia elétrica que interrompa o funcionamento do refrigerador, deve ser feito o registro do fato, data, horário, temperatura e período parado por conta da falha no verso da tabela de registro da temperatura com o assunto “ocorrência”. 9. Guardar a Nota Fiscal de compra do produto em pasta própria para comprovar a rastreabilidade/origem do referido produto. 10. Se tiver outros profissionais no estabelecimento que utilizam produtos termolábeis, realizar o treinamento desse POP com esses profissionais e orientá-los a não deixar a porta do refrigerador aberta. 11. A verificação periódica da validade dos produtos também deve contemplar os produtos termolábeis</p>"}]}, {"id": "b8", "subtitulo": "REFERÊNCIAS LITERÁRIAS", "linhas": [{"col1": "", "col2": "<p>ANVISA, Agência Nacional de Vigilância Sanitária, Resolução-RDC nº 430/2020. ANVISA, Agência Nacional de Vigilância Sanitária, Artigo 18 §6º incisos II e III da Lei Federal nº 8078/1190. ANVISA, Agência Nacional de Vigilância Sanitária, Resolução-RDC nº 63/2011. ANVISA, Agência Nacional de Vigilância Sanitária, Resolução-RDC nº 318/2019</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '004/2026', 'Bioestimuladores', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>BIOESTIMULADORES</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação do procedimento de Bioestimuladores</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<ul><li>Flacidez</li><li>Melhora do contorno facial</li><li>Qualidade da pele</li><li>Melhora global da face</li><li>Aumento e projeção malar e zigomático</li><li>Aumento e projeção do Mento</li></ul>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<ul><li>Reação alérgica conhecida a qualquer um dos componentes</li><li>Presença de inflamação ou infecção aguda e/ou crônica</li><li>Pacientes com predisposição a cicatrizes hipertróficas</li><li>Na presença de preenchimentos permanentes</li><li>Diabéticos</li><li>Doenças auto imunes</li><li>Gravidez</li><li>Lactação</li></ul>"}]}, {"id": "b5", "subtitulo": "TIPOS DE BIOESTIMULADORES", "linhas": [{"col1": "", "col2": "<p>Sculptra (PLLA – ácido poli-l-lático) Planos de aplicação, Reconstituição e preparo: ver Apostila do Curso, conforme descrito no campo ”referências literárias” Radiesse/ Diamond (hidroxiapatita de cálcio - CaHa) Planos de aplicação, Reconstituição e preparo: ver Apostila do Curso, conforme descrito no campo ”referências literárias” Ellansé (policaprolactona) Planos de aplicação, Reconstituição e preparo: ver Apostila do Curso, conforme descrito no campo ”referências literárias” HarmonyCa (ácido hialurônico) Planos de aplicação, Reconstituição e preparo: ver Apostila do Curso, conforme descrito no campo ”referências literárias”</p>"}]}, {"id": "b6", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, propé Profissional – Touca, jaleco, óculos de proteção, máscara e luvas</p>"}]}, {"id": "b7", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Álcool 70% Algodão ou gaze Agulhas Cânulas Seringas Produto Anestésico</p>"}]}, {"id": "b8", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Anamnese</p>", "col2": "<p>Observar o seguinte tópico e registrar na ficha de avaliação do cliente:</p><ul><li>Alergia ao fármaco utilizado no procedimento B. Procedimento 1. Anamnese (tirar foto da área a ser tratada) 2. Identificar a região a ser tratada BIOESTIMULADORES Protocolo:</li><li>Anestesia antes da aplicação</li><li>Desinfecção da maca com álcool 70%</li><li>Maca com lençol de papel descartável</li><li>Higienização das mãos (ver Manual de Rotinas e Procedimentos)</li><li>Acomodar o cliente sentado na maca durante todo o procedimento</li><li>Fazer o registro fotográfico pré-procedimento</li><li>Escolher o produto</li><li>Fazer a marcação na área a ser tratada</li><li>Realizar assepsia na região</li><li>Aplicar a técnica escolhida (conforme Apostila do Curso descrita no campo ”referências literárias”)</li><li>Fazer o registro fotográfico pós-procedimento</li><li>Descartar o produto como lixo perfurocortante (recipiente rígido, conforme Manual de Rotinas e Procedimentos)</li></ul>"}, {"col1": "<p>C. Cuidados pós-procedimento</p>", "col2": "<p>Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente</p>"}, {"col1": "<p>D. Referências literárias</p>", "col2": "<p>Apostila do Curso Bioestimuladores / Thais Valentim - Formação BZP - Bioestimuladores do Zero à Prática</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '005/2026', 'Bioimpedância', '[{"id": "b1", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>A bioimpedância é um exame utilizado para avaliar a composição corporal, como a quantidade de gordura, músculo, água e massa óssea, por meio da passagem de uma leve corrente elétrica pelo corpo</p>"}]}, {"id": "b2", "subtitulo": "RESPONSABILIDADE", "linhas": [{"col1": "", "col2": "<p>Profissional da saúde</p>"}]}, {"id": "b3", "subtitulo": "INDICAÇÃO", "linhas": [{"col1": "", "col2": "<ul><li>Avaliação da composição corporal, incluindo a quantidade de gordura, massa magra, massa óssea e água corporal.</li><li>Acompanhamento de programas de emagrecimento ou ganho de massa muscular.</li><li>Avaliação de retenção de líquidos e monitoramento de condições de saúde relacionadas ao equilíbrio hídrico.</li><li>Planejamento e acompanhamento de tratamentos nutricionais ou esportivos.</li><li>Avaliação da saúde metabólica e do risco cardiovascular</li></ul>"}]}, {"id": "b4", "subtitulo": "CONTRAINDICAÇÕES", "linhas": [{"col1": "", "col2": "<ul><li>Portadores de marcapassos ou outros dispositivos eletrônicos implantáveis, já que a corrente elétrica, mesmo que leve, pode interferir no funcionamento desses dispositivos.</li><li>Pacientes gestantes, especialmente no início da gestação, para evitar a exposição do feto a uma corrente elétrica.</li><li>Pessoas com próteses metálicas extensas ou placas metálicas podem ter os resultados distorcidos.</li><li>Condições agudas, como febre, que podem alterar temporariamente a composição corporal</li></ul>"}]}, {"id": "b5", "subtitulo": "OBSERVAÇÕES", "linhas": [{"col1": "", "col2": "<ul><li>O paciente deve estar em jejum de 4 horas, ou ter evitado grandes refeições nas últimas 2 a 4 horas.</li><li>O exame deve ser realizado preferencialmente em um ambiente tranquilo e com temperatura amena, pois variações de temperatura podem alterar os resultados.</li><li>Evitar exercícios físicos nas últimas 24 horas antes do exame, já que a atividade física altera a distribuição de líquidos corporais.</li><li>O paciente deve esvaziar a bexiga antes do exame.</li><li>A ingestão de cafeína ou bebidas alcoólicas deve ser evitada nas últimas 24 horas, pois podem alterar os níveis de água no corpo.</li><li>Uso de roupas leves, sem acessórios metálicos, é recomendado.</li><li>O paciente deve retirar meias e sapatos e ficar descalço durante a realização do exame</li></ul>"}]}, {"id": "b6", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Profissional – Jaleco, máscara e luvas</p>"}]}, {"id": "b7", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>1. Equipamento de bioimpedância : O mais comum é o analisador de bioimpedância, com eletrodos e balança acoplada. 2. Lenços ou toalhas descartáveis : Para limpar os pés ou as mãos antes da aplicação dos eletrodos. 3. Computador ou tablet : Para armazenar e interpretar os dados do exame. 4. Caneta e formulário : Para registrar os resultados manualmente, se necessário</p>"}]}, {"id": "b8", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "", "col2": "<p>A. Procedimento a. Preparo do paciente:</p><ul><li>Instruções prévias : Certifique-se de que o paciente seguiu as recomendações relacionadas à alimentação, ingestão de líquidos, repouso e exercício físico.</li><li>Explicação sobre o procedimento : Informe o paciente sobre como o exame será feito, sua função e a importância de relaxar durante o processo.</li><li>Retirada de acessórios : Solicite ao paciente que remova relógios, joias e acessórios de metal, pois podem interferir nos resultados. b. Posicionamento do paciente:</li><li>O paciente deve ser posicionado de forma adequada, geralmente em pé sobre a balança de bioimpedância, descalço e com os pés devidamente posicionados nas placas condutoras do equipamento.</li><li>Algumas máquinas exigem que o paciente também segure eletrodos com as mãos, enquanto outras utilizam apenas os pés. c. Aplicação dos eletrodos:</li><li>Caso o equipamento de bioimpedância utilize eletrodos adesivos, coloque-os nas áreas adequadas (mãos, punhos, pés ou tornozelos) para que a corrente elétrica seja distribuída corretamente.</li><li>Certifique-se de que as áreas de contato estejam limpas e secas. d. Execução do exame:</li><li>Ligue o equipamento e inicie a medição. A máquina enviará uma leve corrente elétrica através do corpo, medindo a resistência que a corrente encontra ao atravessar os tecidos corporais.</li><li>A análise leva apenas alguns minutos. O paciente deve permanecer imóvel e relaxado durante o processo. e. Interpretação dos resultados:</li><li>O equipamento fornecerá informações sobre porcentagem de gordura corporal, massa magra, massa óssea, água corporal e outras variáveis, dependendo do modelo utilizado.</li><li>Os resultados podem ser impressos, armazenados digitalmente ou analisados imediatamente pelo profissional de saúde. f. Finalização do exame:</li><li>Após a conclusão do exame, os eletrodos devem ser removidos e descartados de forma adequada, caso sejam descartáveis.</li><li>Limpe o equipamento de bioimpedância conforme necessário, utilizando produtos indicados para esse tipo de material</li></ul>"}, {"col1": "<p>B. Cuidados pós-procedimento</p>", "col2": "<ul><li>Registrar o procedimento realizado, data e horário, carimbo e assinatura de quem realizou o exame em prontuário ou Ficha de atendimento do paciente.</li><li>Reforce com o paciente que os resultados devem ser interpretados pelo profissional de saúde responsável e que os dados obtidos podem variar em função de fatores como hidratação, nível de atividade física e estado de saúde atual.</li><li>Agende um retorno ou acompanhamento, se necessário, para avaliação mais detalhada dos resultados</li></ul>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>KUSHNER, R. F.; SCHOELLER, D</p>"}, {"col1": "<p>A. Estimation of</p>", "col2": "<p>Total Body Water by Bioelectrical Impedance Analysis . The American Journal of Clinical Nutrition, 1993. THOMAS, B.; BISHOP,</p>"}, {"col1": "<p>J. Manual of</p>", "col2": "<p>Dietetic Practice . Wiley-Blackwell, 2013. BRASIL. Ministério da Saúde. Agência Nacional de Vigilância Sanitária (ANVISA) . Normas técnicas para realização de exames de bioimpedância em clínicas de saúde</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '006/2026', 'Biorressonância quântica', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>nº ______ BIORRESSONÂNCIA QUÂNTICA</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de realização da biorressonância quântica. A Biorressonância quântica funciona conforme a medicina quântica (ou oscilatória), que identifica as oscilações dos elétrons que compõem o núcleo atômico, que é o que altera o material construtivo do átomo e células e, consequentemente, órgãos. A manipulação das oscilações eletromagnéticas endógenas que correspondem à condição patológica do paciente é utilizada para diagnostico e tratamento. Para Periklis et al (2019), a biorressonância é um método físico holístico que pode ser usado de forma diagnóstica e terapêutica para tratar várias doenças. A biorressonância usa as ondas eletromagnéticas que recebe do paciente. Esse método biofísico de tratamento altera o campo de energia do organismo afetado, aumentando a eficácia do sistema autoimune, melhorando assim a saúde geral do paciente (PERIKLIS et al, 2019)</p>"}]}, {"id": "b3", "subtitulo": "RESPONSABILIDADE", "linhas": [{"col1": "", "col2": "<p>Profissional da saúde</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>1. Detecção de desequilíbrios energéticos: A biorressonância magnética quântica é frequentemente promovida como uma ferramenta para detectar desequilíbrios ou distúrbios energéticos no corpo, que supostamente podem estar associados a diversas condições de saúde. 2. Avaliação da saúde geral: Alguns defensores afirmam que a biorressonância magnética quântica pode ser usada para avaliar a saúde geral do corpo, identificando áreas de preocupação ou áreas que podem precisar de suporte adicional. 3. Avaliação de sensibilidades alimentares: A técnica é frequentemente comercializada como uma ferramenta para identificar sensibilidades alimentares e intolerâncias, ajudando os indivíduos a determinar quais alimentos podem estar causando problemas de saúde. 4. Tratamento de condições crônicas: Algumas pessoas buscam a biorressonância magnética quântica como uma opção de tratamento para condições crônicas, como dor crônica, fadiga, distúrbios do sono, entre outros. É importante ressaltar que as indicações mencionadas acima são alegadas e não são baseadas em evidências científicas reconhecidas. Antes de considerar qualquer forma de tratamento ou avaliação de saúde pela biorressonância magnética quântica, é fundamental que o profisional consulte seu conselho de classe para não ferir a ética profissional atuando fora do seu rol de atividades permitidas</p>"}]}, {"id": "b5", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>1. Pacientes com dispositivos eletrônicos implantados: Alguns defensores da biorressonância magnética quântica afirmam que pacientes com dispositivos eletrônicos implantados, como marca-passos ou bombas de insulina, podem não ser candidatos ideais para este tipo de procedimento, devido à possibilidade de interferência eletromagnética. 2. Gravidez: Algumas fontes sugerem que a biorressonância magnética quântica pode não ser apropriada para mulheres grávidas, devido à falta de dados sobre sua segurança durante a gravidez. nº ______ BIORRESSONÂNCIA QUÂNTICA 3. Pacientes com doenças graves ou emergências médicas: A biorressonância magnética quântica não é uma ferramenta de diagnóstico ou tratamento reconhecida para condições médicas graves ou emergências médicas. Portanto, não deve ser utilizada como substituto para cuidados médicos convencionais nessas situações. É importante ressaltar que as contraindicações mencionadas acima são alegadas e não são baseadas em evidências científicas reconhecidas. Antes de considerar qualquer forma de tratamento ou avaliação de saúde pela biorressonância magnética quântica, é fundamental que o profisional consulte seu conselho de classe para não ferir a ética profissional atuando fora do seu rol de atividades permitidas</p>"}]}, {"id": "b6", "subtitulo": "CONTEXTO", "linhas": [{"col1": "", "col2": "<p>O método da biorressonância foi criado por Frans Morrel (considerado pai da Biorressonância). Em 1977, tendo uma longa experiência em eletroacupuntura, ele pensou que seus tratamentos poderiam ser mais precisos se ele pudesse usar as vibrações eletromagnéticas do próprio corpo do paciente. Assim, o primeiro dispositivo eletrônico que poderia receber e retornar frequências eletromagnéticas de / para o corpo usando eletrodos foi construído. Morell introduziu o modelo de tratamento usando os sinais do próprio corpo do paciente, que foi inicialmente chamado de tratamento MORA (PERIKLIS et al, 2019). Para que seja alcançada tal avaliação, o método é realizado com um aparelho eletrônico, que identifica as frequências e desequilíbrios do corpo humano, quantificando índices de forma rápida. Sensores são colocados e reconhecem as energias do corpo humano por meio de ondas eletromagnéticas. Essa avaliação é feita em cada sistema do corpo. Ao final da avaliação, é gerado um relatório apontando as deficiências, funções aferidas e sugestões de tratamento</p>"}]}, {"id": "b7", "subtitulo": "ÉTICA PROFISSIONAL", "linhas": [{"col1": "", "col2": "<p>O profissional que vislumbra o uso de técnicas e equipamentos que não são, respectivamente, reconhecidas e homologados no Brasil pelo seu conselho de classe pode-se expor a denúncias e ser submetido à sanções profissionais. Vale lembrar que o uso de equipamentos com finalidade terapêutica, tais como os de uso para a realização do exame de biorressonância, devem ser registrados na ANVISA do Brasil. A terapia de Biorressonância Quântica ainda está no campo do estudo experimental, carece de validação científica e não faz parte do rol de práticas integrativas e complementares regulamentadas pelo Ministério da Saúde pelos conselhos de classe profisisonal. Portanto, antes de considerar qualquer forma de tratamento ou avaliação de saúde pela biorressonância magnética quântica, é fundamental que o profisional consulte seu conselho de classe para não ferir a ética profissional atuando fora do seu rol de atividades permitidas</p>"}]}, {"id": "b8", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Profissional – Touca, jaleco, máscara e luvas</p>"}]}, {"id": "b9", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<ul><li>Equipamento de biorressonância magnética quântica</li><li>Eletrodos ou sensores</li><li>Computador ou console de controle nº ______ BIORRESSONÂNCIA QUÂNTICA</li><li>Software de análise</li></ul>"}]}, {"id": "b10", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "", "col2": "<p>A. Procedimento 1. Avaliação inicial do paciente: Antes de iniciar o procedimento de biorressonância magnética quântica, o profissional de saúde deve realizar uma avaliação detalhada do paciente, incluindo histórico médico, sintomas relatados e qualquer outra informação relevante sobre a saúde do paciente. 2. Explicação do procedimento: O profissional de saúde deve explicar claramente ao paciente como funciona a biorressonância magnética quântica, incluindo suas limitações, benefícios e possíveis riscos. É fundamental garantir que o paciente compreenda completamente o procedimento e dê seu consentimento informado. 3. Preparação do equipamento: Certifique-se de que o equipamento de biorressonância magnética quântica esteja calibrado e funcionando corretamente antes de iniciar o procedimento. Siga as instruções do fabricante para garantir a precisão e a segurança do equipamento. 4. Posicionamento do paciente: Posicione o paciente de forma confortável e relaxada, geralmente sentado ou deitado, dependendo do equipamento utilizado. Certifique-se de que o paciente esteja calmo e tranquilo durante o procedimento. 5. Aplicação dos sensores ou eletrodos: Coloque os sensores ou eletrodos necessários para o procedimento nos locais apropriados do corpo do paciente, conforme indicado pelo equipamento de biorressonância magnética quântica. Isso pode envolver a fixação de eletrodos nas mãos, pés ou cabeça do paciente. 6. Realização da leitura: Inicie o procedimento de biorressonância magnética quântica de acordo com as instruções do equipamento. Isso pode incluir a transmissão de sinais magnéticos ou elétricos através dos sensores ou eletrodos e a análise das respostas do corpo do paciente. 7. Interpretação dos resultados: Analise os resultados obtidos durante o procedimento de biorressonância magnética quântica e interprete-os em conjunto com as informações clínicas do paciente. Esteja ciente das limitações e da falta de validade científica dessa técnica e evite fazer afirmações não fundamentadas sobre diagnósticos ou tratamentos. 8. Discussão com o paciente: Discuta os resultados do procedimento com o paciente de forma clara e objetiva, explicando qualquer informação relevante e respondendo às perguntas ou preocupações do paciente. Se necessário, encaminhe o paciente a um profissional de saúde qualificado para uma avaliação médica convencional. B. Cuidados pós-procedimento 1. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. 2. Entregar uma via do Termo para o cliente. 3. Registre detalhadamente os resultados do procedimento de biorressonância magnética quântica no prontuário do paciente, juntamente com outras informações relevantes sobre sua saúde. Programe o seguimento adequado conforme necessário, com base nos resultados obtidos e nas necessidades do paciente. nº ______ BIORRESSONÂNCIA QUÂNTICA</p>"}, {"col1": "<p>C. Referência literária</p>", "col2": "<p>Observa-se uma escassez de estudos nacionais e internacionais com evidências robustas para embasar o uso do método em questão. 1. Manual de Intrução de Uso do fabricante do aparelho. 2. COREN. Conselho Regional de Enfermagem. Parecer Técnico COREN-DF nº 09/2020. Realização de Biorressonância em Consultório privado de enfermagem. Disponível no link: https://coren-df.gov.br/site/wp-content/uploads/2021/05/pt092021.pdf. Acesso em 30 mar.2024. 3. Deepak Chopra. Quantum Healing: Exploring the Frontiers of Mind/Body Medicine. 4. Periklis et al. The Effectiveness of Bioresonance Method on Human Health . The Open Epidemilogy Journal. v.8, 2019. 8p. Disponível em: https://openepidemiologyjournal.com/VOLUME/8/PAGE/1/ Acesso em 30 mar.2024</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '007/2026', 'Consulta Estética', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>CONSULTA SAÚDE ESTÉTICA</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Este protocolo destina-se a oferecer subsídios para nortear as ações do profissional, na área da saúde estética, para a promoção do conforto e bem-estar de seu paciente/cliente</p>"}]}, {"id": "b3", "subtitulo": "ALCANCE", "linhas": [{"col1": "", "col2": "<p>Este documento aplica-se a todos profissionais da área da saúde que possuem regulamentação aprovada para tal prática, conforme abaixo:</p><ul><li>Conselho Federal de Biologia – Resolução CFBio nº 582/2020</li><li>Conselho Federal de Biomedicina – Resolução CFBM nº 241/2014</li><li>Conselho Federal de Odontologia – Resolução CFO nº 198/2019</li><li>Conselho Federal de Enfermagem – Resolução COFEN nº 626/2020</li><li>Conselho Federal de Farmácia – Resolução CFF nº 616/2015 e 645/2017</li><li>Conselho Federal de Fisioterapia – Resolução COFFITO nº 394/2011</li><li>Conselho Federal de Medicina – Resolução CFM nº 2221/2018</li><li>Lei nº 13.643/2018 – Regulamenta as profissões de Esteticista, que compreende o Esteticista e Cosmetólogo, e de Técnico em Estética</li></ul>"}]}, {"id": "b4", "subtitulo": "RECURSOS NECESSÁRIOS", "linhas": [{"col1": "", "col2": "<p>i. Ficha de anamnese ii. Prontuário do cliente/paciente iii. Caderno de Intercorrências iv. Termo de Consentimento para cada procedimento v. POP ( ) para cada procedimento vi. Manual de Rotinas e Procedimentos vii. PGRSS (plano de gerenciamento de resíduos)</p>"}]}, {"id": "b5", "subtitulo": "ATENDIMENTO À POPULAÇÃO COM DISFUNÇÕES ESTÉTICAS NO ESTABELECIMENTO DE SAÚDE E DE INTERESSE PARA A SAÚDE", "linhas": [{"col1": "", "col2": "<p>Atender pessoas com disfunções estéticas demanda aperfeiçoamento técnico constante visto a complexidade dos casos. Faz-se necessário desenvolver habilidades e atitudes concernentes à abordagem integral dos indivíduos, bem como a organização do processo de trabalho. Assim, esta prática é insegura quando realizada por profissionais que não são devidamente habilitados e qualificados na área da saúde estética. sem autorização prévia. PROTOCOLO DE CONSULTA Código 0001 Edição Primeira CONSULTA SAÚDE ESTÉTICA Cada formação profissional poderá exercer as atividades na área da saúde estética de acordo com o limite de atuação disposto nas suas respectivas legislações. É de competência do profissional que atua na área da saúde estética: realizar consulta (anamnese); prescrever e/ou orientar os cuidados domiciliares e orientações para o autocuidado aos pacientes/clientes submetidos aos procedimentos estéticos; registrar em prontuário todas as ocorrências e dados referentes ao procedimento; realizar processo de seleção de compra de materiais para uso estético na instituição de saúde; estabelecer protocolos dos procedimentos estéticos; solicitar exames (se necessário); manter-se atualizado através de treinamentos, cursos específicos, capacitação, entre outros. 4.2 Consulta à pessoa com disfunção estética O atendimento adequado à pessoa com disfunção estética deve considerar sua condição geral de saúde, investigando-se fatores que interfiram no plano de tratamento a ser adotado, através da aplicação da ficha de anamnese . 4.3 Avaliação do cliente/paciente As informações colhidas no momento da avaliação do paciente devem ser registradas pelo profissional em um protocolo padronizado conhecido como “ficha de anamnese”, a qual deve ser preenchida, assinada pelo cliente/paciente e arquivada no prontuário do cliente/paciente. 4.4 Registro das informações do cliente/paciente A cada visita ao estabelecimento de saúde e de interesse para a saúde, o cliente/paciente deve rubricar a sua ficha de atendimento, a qual fica dentro do prontuário do cliente/paciente, onde deve estar registrado o acompanhamento e evolução do seu tratamento. O profissional deve registrar na ficha de atendimento o procedimento realizado no cliente/paciente, com a respectiva data, nome dos produtos utilizados, número dos lotes dos produtos utilizados, nome dos equipamentos utilizados e se o procedimento ocorreu bem ou não. Também serão coletados os dados do cliente/paciente para fins de cadastro na ficha do cliente/paciente respeitando-se a Lei Geral de Proteção de Dados Pessoais (LGPD), a qual visa proteger os direitos de liberdade e de privacidade, criando normas a serem seguidas por empresas e governos para a coleta e o tratamento de dados pessoais (como nome, CPF, endereço) e de dados sensíveis (como biometria e informações sobre política e religião). sem autorização prévia. CONSULTA SAÚDE ESTÉTICA 4.5 Caderno de Intercorrências Caso aconteça qualquer intercorrência durante ou após a realização do procedimento no cliente/paciente, o profissional deve registrar no seu “Caderno de Intercorrências” o ocorrido, qual foi a ação tomada para reverter a situação e qual o procedimento adotado para prevenir que tal situação ocorra novamente. 4.6 Contrato de Prestação de Serviço Para todo e qualquer plano de tratamento deve ser elaborado um Contrato descrevendo, no mínimo, os procedimentos que serão realizados, o número de sessões estabelecidas, o orçamento e a data de vigência do referido contrato. Coletar a assinatura do cliente/paciente e arquivar uma via no prontuário do cliente/paciente. Entregar uma via para o cliente/paciente. 4.7 Termo de Consentimento Antes de realizar qualquer procedimento, o profissional deve assegurar que o cliente/paciente esteja ciente da técnica que será utilizada e, portanto, o profissional deverá tirar todas as dúvidas do cliente/paciente e solicitar que o cliente/paciente leia e assine o termo de consentimento antes de realizar o procedimento. Uma via desse documento deve ser arquivada no prontuário do cliente/paciente. Entregar uma via para o cliente/paciente. 4.8 Procedimentos Gerais Realizar a limpeza do ambiente, dos utensílios e artigos, assim como a higienização das mãos antes de iniciar qualquer procedimento, conforme descrito no Manual de Rotinas e Procedimentos e nos respectivos POP’s ( ). A segregação, manuseio e descarte dos resíduos deve ser de acordo com o Plano de Gerenciamento de Resíduos (PGRSS) do estabelecimento. Cada procedimento deve ter seu próprio POP ( ) devidamente assinado e datado. Todos os documentos sanitários desse estabelecimento ficam organizados na pasta sanitária para fácil e rápida consulta. Não será permitida a consumação de bebida e/ou alimento dentro da sala de atendimento por se tratar de uma área crítica. O profissional deve garantir que o seu local de trabalho atende às normas sanitárias, as condutas de biossegurança e o código de ética do seu Conselho de Classe. sem autorização prévia. CONSULTA SAÚDE ESTÉTICA</p>"}]}, {"id": "b7", "subtitulo": "REFERÊNCIA", "linhas": [{"col1": "", "col2": "<ul><li>Resolução CFBio nº 582/2020</li><li>Resolução CFBM nº 241/2014</li><li>Resolução CFO nº 198/2019</li><li>Resolução COFEN nº 626/2020</li><li>Resolução CFF nº 616/2015 e 645/2017</li><li>Resolução COFFITO nº 394/2011</li><li>Resolução CFM nº 2221/2018</li><li>Lei nº 13.643/2018 sem autorização prévia. ELABORADO POR: APROVADO POR: DATA DE APROVAÇÃO: sem autorização prévia</li></ul>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '008/2026', 'Corrente Russa', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>CORRENTE RUSSA</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação do procedimento de corrente russa (eletroestimulação). A corrente russa é um recurso utilizado pela eletroterapia na área de estética corporal como forma de trabalhar a flacidez muscular. O objetivo dessa modalidade terapêutica é propiciar, em decorrência da contração muscular, o fortalecimento ou hipertrofia muscular, bem como o aumento da circulação sanguínea e linfática, melhorando assim o trofismo dos tecidos</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Flacidez Celulite Adiposidade localizada</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Transtornos de sensibilidade Gravidez Sobre áreas onde se localizam metais Portadores de marcapasso cardíaco</p>"}]}, {"id": "b5", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, máscara Profissional – Touca, máscara e luvas</p>"}]}, {"id": "b6", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Algodão ou gaze Gel Equipamento</p>"}]}, {"id": "b7", "subtitulo": "OBERVAÇÕES", "linhas": [{"col1": "", "col2": "<p>Geralmente os aparelhos de corrente russa apresentam parâmetros de pulsos combinados entre o tempo ON e o tempo OFF necessários para a despolarização e repolarização</p>"}]}, {"id": "b8", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>Avaliação: a. Identificar a área a ser tratada Protocolo: Desinfecção da maca com álcool 70% Maca com lençol de papel descartável Higienização das mãos (ver Manual de Rotinas e Procedimentos) Acomodar o cliente na maca durante todo o procedimento Fazer o registro fotográfico pré-procedimento Realizar assepsia na região CORRENTE RUSSA Acoplar corretamente as placas ou faixas condutoras com gel condutor. A pele deve ser previamente limpa na área onde serão colocados os eletrodos. Verificar se as placas ou faixas condutoras estão bem posicionadas e fixadas A colocação das placas ou faixas condutoras deverá ser realizada com o equipamento ligado, mas com as intensidades zeradas. Jamais manuseie as placas ou faixas condutoras durante a terapia se elas não estiverem com sua intensidade zerada Não ligue ou desligue totalmente o equipamento com os eletrodos conectados ao paciente Use somente os eletrodos e cabos originais do equipamento</p>"}]}, {"id": "b9", "subtitulo": "ATENÇÃO", "linhas": [{"col1": "", "col2": "<p>Ligar o aparelho e seguir o protocolo, conforme instrução do fabricante Fazer o registro fotográfico pós-procedimento B. Cuidados pós-procedimento a. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. b. Anotar na ficha do cliente todos os produtos e equipamentos utilizados nesse procedimento com seus respectivos números de lotes, data de validade e nome do fabricante</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>AGNE, Jones Eduardo, Eu sei Eletroterapia. Santa Maria: Pallotti, 2011 AGNE, Jones Eduardo, Eletrotermofototerapia. Santa Maria: O Autor, 2013 BORGES, Fábio dos Santos. Dermato - Funcional: modalidades terapêuticas nas disfunções estéticas. São Paulo: Phorte, 2006</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '009/2026', 'Criofrequência', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>nº_________ CRIOFREQUÊNCIA</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação do procedimento de criofrequência, também conhecida como “radiofrequência fria”. Trata-se de um aplicador que emite ondas de radio e faz com que haja agitação das moléculas de água. Essa agitação e rotação das moléculas de água, somados com o atrito do aplicador na pele, geram calor nos tecidos da pele. A criofrequência utiliza uma ponteira ultracongelada, que esfria a pele a 10 graus negativos, destruindo as células de gordura e causando efeito lifting. Posteriormente, o calor provoca um choque térmico que retrai o colágeno, estimulando a formação de novas fibras</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<ul><li>Celulite</li><li>Gordura localizada</li><li>Flacidez de pele, rugas e linhas de expressão Os principais efeitos fisiológicos gerados pelo aquecimento interno são:</li><li>Vasodilatação e Aumento da Circulação Sanguínea;</li><li>O aumento da temperatura causa diminuição da viscosidade dos líquidos, promovendo uma melhora circulatória e redução de edema;</li><li>Neocolagênese e Neoelastogênese: estimulação do fibroblasto a produzir novas fibras de colágeno e elastina;</li><li>Alteração na extensibilidade do colágeno;</li><li>Efeito Lifting</li></ul>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<ul><li>Marcapasso;</li><li>Câncer;</li><li>Gestantes;</li><li>Implantes (metal, silicone e definitivo);</li><li>Dermatites;</li><li>Epilepsia; nº_________ CRIOFREQUÊNCIA</li><li>Alteração de sensibilidade na região tratada;</li><li>Patologias descompensadas</li></ul>"}]}, {"id": "b5", "subtitulo": "TIPOS DE TRATAMENTO", "linhas": [{"col1": "", "col2": "<p>Para gordura localizada, é utilizado um aplicador monopolar e uma frequência mais baixa, fazendo com que a onda atinja a hipoderme. - Para celulite e flacidez tissular corporal, é utilizado um aplicador multipolar, ou seja, com vários polos. Nesse caso, a frequência pode ser intermediária. - Para rejuvenescimento facial, linhas de expressão e rugas, é utilizado um aplicador multipontas também, geralmente bipolar pela ergonomia de se adaptar à face. No rosto, também podemos fazer tratamento de papada. Quando o equipamento permite, colocamos uma frequência menor para atingir gordura ou uma frequência maior para atingir a derme e estimular a produção de colágeno e elastina</p>"}]}, {"id": "b6", "subtitulo": "INTERVALO SUGERIDO ENTRE AS SESSÕES", "linhas": [{"col1": "", "col2": "<p>Para tratamentos em que se objetiva estímulo de fibroblasto para produção de colágeno, elastina e ácido hialurônico, a média de intervalo entre as sessões é de 15 dias e o número total de sessões varia de acordo com cada paciente, sendo uma média de cinco sessões. Para tratamentos em que o principal objetivo é diminuição de medidas e modelamento do contorno corporal, o intervalo entre as sessões pode ser de três dias, podendo realizar duas sessões por semana</p>"}]}, {"id": "b7", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, propé Profissional – Touca, máscara, jaleco e luvas</p>"}]}, {"id": "b8", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Algodão ou gaze Equipamento</p>"}]}, {"id": "b9", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "", "col2": "<p>nº_________ CRIOFREQUÊNCIA</p>"}, {"col1": "<p>A. Procedimento</p>", "col2": "<p>Avaliação: a. Identificar a área a ser tratada e calcular o tempo</p>"}]}, {"id": "b10", "subtitulo": "OBSERVAÇÃO", "linhas": [{"col1": "", "col2": "<p>É de extrema importância que se respeite o tempo adequado do tratamento para que o tratamento tenha resultado eficaz. Protocolo: 1. Desinfecção da maca com álcool 70% 2. Maca com lençol de papel descartável 3. Higienização das mãos (ver Manual de Rotinas e Procedimentos) 4. Acomodar o cliente na maca durante todo o procedimento 5. Fazer o registro fotográfico pré-procedimento 6. Realizar assepsia na região 7. Ligar o aparelho e seguir o protocolo, conforme instrução do fabricante 8. Definir o tempo de acordo com a avaliação da área 9. Realizar a aplicação: - Técnica de aplicação na bochecha: A aplicação da Criofrequencia facial na região da bochecha deve acontecer no sentido linear em toda a região, com movimentos ascendentes ou circulares em direção ao couro cabeludo, concentrando energia sobre esta área. - Técnica de aplicação na papada: Obs: essa programação do tratamento de Criofrequencia na papada é contraindicada para pessoas que possuem implante metálico na região facial. Nessa aplicação, deve-se posicionar a placa metálica na região da escápula, do mesmo lado que fará a aplicação da papada. Por exemplo: se for tratar a papada direita, então a nº_________ CRIOFREQUÊNCIA placa será posicionada na escápula direita. A placa metálica, definida como Placa Monopolar, é a responsável pelo tratamento da gordura, pois nos permite alcançar o tecido adiposo. A aplicação deve acontecer no sentido linear horizontal, com movimentos em direção ao lóbulo da orelha, sem retirar o contato do cabeçote, concentrando energia sobre esta área. - Técnica de aplicação no pescoço: Obs: essa programação é contraindicada para pessoas que possuem implante metálico na região facial e a aplicação não deve ser realizada sobre a área de tireoide. Nessa aplicação, deve-se posicionar a placa metálica na região da escápula, do mesmo lado em que fará a aplicação do pescoço. Por exemplo: se tratar o lado direito do pescoço, então a placa deve ser posicionada na escápula direita. a aplicação deve acontecer no sentido circular, sem retirar o contato do cabeçote, concentrando energia sobre esta área. - Técnica de aplicação na cintura: Obs: nesse tratamento, para pessoas que possuem implante metálico na região do abdômen, essa programação é contraindicada. Posicionar a placa metálica na região posterior do tronco, do mesmo lado que faremos a aplicação da cintura. Por exemplo: trataremos a cintura direita, então a placa será posicionada no tronco posterior direito. A aplicação deve acontecer no sentido linear horizontal, acompanhando o contorno da área, sem retirar o contato do cabeçote, concentrando energia sobre esta área. - Técnica de aplicação nos flancos: nº_________ CRIOFREQUÊNCIA Obs: nesse tratamento, para pessoas que possuem implante metálico na região do abdômen, essa programação é contraindicada. Posicionar a placa metálica na região posterior do tronco, do mesmo lado que faremos a aplicação dos flancos. Por exemplo: trataremos o flanco direito, então a placa será posicionada no tronco posterior direito. A aplicação deve acontecer no sentido linear horizontal, acompanhando o contorno da área, ou circular, sem retirar o contato do cabeçote, concentrando energia sobre esta área. - Técnica de aplicação no abdomen superior: Obs: nesse tratamento, para pessoas que possuem implante metálico na região do abdômen, essa programação é contraindicada. Posicionar a placa metálica na região posterior do tronco, paralelo à região superior do abdômen. A aplicação da Criofrequência corporal na região do abdômen superior deve acontecer no sentido linear horizontal, acompanhando o contorno da área, ou circular sem retirar o contato do cabeçote, concentrando energia sobre esta área. - Técnica de aplicação no abdomen inferior: Obs: nesse tratamento, para pessoas que possuem implante metálico na região do abdômen, essa programação é contraindicada. Posicionar a placa metálica na região posterior do tronco, paralelo à região inferior do abdômen. A aplicação deve acontecer no sentido linear horizontal, acompanhando o contorno da área, ou circular sem retirar o contato do cabeçote, concentrando energia sobre esta área. nº_________ CRIOFREQUÊNCIA 10. Fazer o registro fotográfico pós-procedimento B. Cuidados pós-procedimento a. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. b. Anotar na ficha do cliente todos os produtos e equipamentos utilizados nesse procedimento com seus respectivos números de lotes, data de validade e nome do fabricante</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>Criofrequência: a revolução no combate à gordura localizada. HSMED. Disponível em: . Acesso em 09 Dez. 2022</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '010/2026', 'Criolipólise', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>CRIOLIPÓLISE</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de criolipólise. É o resfriamento localizado do tecido adiposo subcutâneo de forma não invasiva, causando paniculite fria localizada, morte adipocitária por apoptose e diminuição do contigente adiposo subcutâneo localizado</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Gordura localizada Celulite</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Hérnia no local da aplicação Lesões inflamatórias e/ou infecciosas na pele do local de aplicação Gestantes Pouca gordura na área-alvo Crioglobulinemia Lúpus eritematoso sistêmico Artrite reumatoide Hemoglobinúria paroxística ao frio Alterações de sensibilidade Tumor ou câncer Feridas abertas Cirurgia recente Áreas com circulação periférica insuficiente Alergia ou hipersensibilidade ao frio Uso de anticoagulantes Diabetes Doença neurológica conhecida Angioedema hereditário Trombofilia Varizes no local da aplicação Excesso de peso (obesidade)</p>"}]}, {"id": "b5", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, máscara e propé Profissional – Touca, máscara, jaleco, óculos de proteção e luvas</p>"}]}, {"id": "b6", "subtitulo": "APLICAÇÃO DE MÚLTIPLAS ÁREAS", "linhas": [{"col1": "", "col2": "<p>Conforme a extensão da área a ser tratada e o tamanho do aplicador, várias aplicações podem ser necessárias para atingir de forma eficaz toda a área-alvo. Podem ser feitas aplicações em várias áreas do corpo numa mesma sessão. CRIOLIPÓLISE</p>"}]}, {"id": "b7", "subtitulo": "TEMPO DE APLICAÇÃO", "linhas": [{"col1": "", "col2": "<p>O tempo ideal de aplicação é de 60 minutos (sempre verificar com o fabricante de cada equipamento)</p>"}]}, {"id": "b8", "subtitulo": "NÚMERO DE SESSÕES E INTERVALO ENTRE AS SESSÕES", "linhas": [{"col1": "", "col2": "<p>Não há uma regra específica sobre o número exato de aplicações necessárias para se obter um resultado satisfatório, sendo comum uma média de uma a três aplicações. Dependendo da espessura da camada de gordura tratada, pode ser necessária mais de uma sessão a fim de atingirmos níveis subcutâneos mais profundos. Os resultados começam a ser verificados a partir de 30 a 60 dias (às vezes, até 90 dias) após o procedimento. Relatos da literatura recomendam uma sessão a cada oito semanas (em média, dois meses). Recomenda-se que a análise final dos resultados do tratamento não deve se fixar no prazo de dois meses após o atendimento, pois os resultados da criolipólise podem ocorrer além dos dois meses após o tratamento</p>"}]}, {"id": "b9", "subtitulo": "TEMPERATURA DO EQUIPAMENTO", "linhas": [{"col1": "", "col2": "<p>Existe uma grande variedade de equipamentos disponíveis no mercado. Diante disso, o parâmetro relacionado ao ajuste da temperatura não tem um padrão definido. Importante alertar que a temperatura ajustada no equipamento não será aquela que ocorrerá no tecido adiposo, principalmente em níveis profundos</p>"}]}, {"id": "b10", "subtitulo": "ATENÇÃO", "linhas": [{"col1": "", "col2": "<p>No caso de um aparelho de locação, solicitar o comprovante da última calibração/manutenção a fim de assegurar o bom funcionamento do equipamento. Também deve-se solicitar o Alvará CRIOLIPÓLISE Sanitário da empresa que faz a locação do equipamento</p>"}]}, {"id": "b11", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Equipamento Membrana anticongelante Aplicador (também chamado de manopla, manípulo ou alça de tratamento)</p>"}]}, {"id": "b12", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>Avaliação: a. Identificar a área a ser tratada (abdome, flancos, costas, etc) b. Fazer a anamnese c. Determinar o tamanho do aplicador para cada área/região a ser tratada d. Determinar o tamanho da membrana anticongelante (pequena, média ou grande) a ser utilizada em cada área/região a ser tratada Protocolo: Fazer o registro fotográfico pré-procedimento Demarcar a região a ser tratada antes de iniciar o tratamento Higienização das mãos (ver Manual de Rotinas e Procedimentos) Realizar assepsia na região Posicionar a membrana anticongelante entre a pele e o aplicador O aplicador deve ser posicionado totalmente sobre a membrana, que deve cobrir toda a área a ser tratada, principalmente onde as placas refrigeradoras estarão em contato com a pele Respeitar a temperatura e o tempo de aplicação indicado pelo fabricante de cada equipamento Após a remoção do aplicador, realizar massagem manual pós-procedimento Fazer o registro fotográfico pós-procedimento B. Cuidados pós-procedimento a. Anexar na ficha do cliente uma via do Termo de Consentimento com os CRIOLIPÓLISE cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. b. Anotar na ficha do cliente o nome, lote e nome do fabricante da membrana anticongelante, assim como o respectivo nº de registro do aparelho na Anvisa, nome e CNPJ da empresa responsável pela locação</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>Borges, F. dos</p>"}, {"col1": "<p>S. Dermato-Funcional</p>", "col2": "<p>Modalidades terapêuticas nas disfunções estéticas Borges, F.S.; SCORZA, F.A. Fundamentos de Criolipólise. Revista Fisioterapia Ser, v.9, n.4, 2014 Lee. K.R. Clinical efficacy of fat reduction on the thigh of Korean women through cryolipolysis. Journal of obesity and weight loss therapy, 2013 Avram, M.M.; Harry, R.S. Cryolipolysis for subcutaneous fat layer reduction. Lasers in surgery and medicine, v.41 Krueger, N. et al. Cryolipolysis for noninvasive body contouring: clinical efficacy and patient satisfaction,</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '011/2026', 'Crioterapia', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>CRIOTERAPIA</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de Crioterapia. Trata-se do resfriamento local com o intuito de promover uma diminuição do metabolismo da área, resultando em um menor consumo de oxigênio e nutrientes</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Celulite (FEG)</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Alteração de sensibilidade local Intolerância ou alergia ao frio Hemoglobinúria paroxística ao frio (anemia hemolítica crônica adquirida rara) Crioglobulinemia (presença de proteínas anormais no sangue, as crioglobulinas) Tumores na área a ser tratada Afecção cutânea na área tratada Alergia aos produtos utilizados</p>"}]}, {"id": "b5", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, propé Profissional – Touca, máscara, jaleco, óculos de proteção e luvas</p>"}]}, {"id": "b6", "subtitulo": "OBSERVAÇÃO", "linhas": [{"col1": "", "col2": "<p>A crioterapia é utilizada na FEG por meio de cosméticos com princípios ativos que promovem resfriamento tecidual local, como cânfora ou mentol. A bandagem crioterápica normalmente é indicada no tratamento da FEG quando este se mostra associado à gordura localizada. Na técnica da crioterapia, pode-se associar o gel à bandagem crioterápica para potencializar o resfriamento. O tempo de aplicação é individual, respeitando-se a tolerância de cada cliente. Porém, quanto maior a espessura do tecido adiposo, maior deve ser o tempo de aplicação. Normalmente, o tempo fica em torno de 30 minutos, e a aplicação pode ser feita em diversas regiões ao CRIOTERAPIA mesmo tempo, como abdômen, braços e coxas</p>"}]}, {"id": "b7", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Algodão ou gaze Atadura de crepom Gel Loção</p>"}]}, {"id": "b8", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>Avaliação: a. Identificar a área a ser tratada b. Fazer a anamnese Protocolo: a. Higienização das mãos (ver Manual de Rotinas e Procedimentos) b. Fazer o registro fotográfico pré-procedimento c. Realizar assepsia na região com o cliente em pé d. Aplicar o gel crioterápico na pele da região escolhida com o auxílio de uma espátula e. Colocar a atadura de crepom na loção crioterápica, enrolando-a por cima do local onde foi aplicado o gel, realizando-se uma pequena compressão f. Respeitar o tempo de aplicação individual g. Remover a bandagem e os produtos h. Fazer o registro fotográfico pós-procedimento CUIDADOS: - Não expor a região tratada ao sol logo após a aplicação, pois alguns produtos são fotossensibilizantes - cuidado ao realizar correntes elétricas no local logo após a bandagem, em razão da diminuição da sensibilidade - Não pressionar muito o local com a bandagem, evitando dificultar o retorno CRIOTERAPIA sanguíneo e, consequentemente, lesões por hipóxia B. Cuidados pós-procedimento a. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. b. Anotar na ficha do cliente todos os produtos utilizados nesse procedimento com seus respectivos números de lotes, data de validade e nome do fabricante</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>Borges, F. dos</p>"}, {"col1": "<p>S. Dermato-Funcional</p>", "col2": "<p>Modalidades terapêuticas nas disfunções estéticas</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '012/2026', 'Dedetização', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>CONTROLE DE PRAGAS / DEDETIZAÇÃO</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever como deve ser realizado o controle de pragas no estabelecimento. CONTROLE QUÍMICO: O estabelecimento deve apresentar comprovante de execução de serviço fornecido pela empresa especializada contratada, contendo as informações estabelecidas em legislação sanitária específica. Esta empresa deve ainda fornecer um certificado do serviço prestado, onde constam os dados da empresa, os produtos que foram utilizados e a data de validade do serviço, ou seja, quando deverá ser realizado um novo controle. CONTROLE CORRETIVO: É importante definir que o controle preventivo de pragas é aquele que o estabelecimento deve realizar todos os dias em relação a higiene e organização do estabelecimento, equipamentos e utensílios para que não sejam atrativos para pragas. E o controle corretivo é aquele que deve ser adotado quando o controle preventivo não estiver sendo eficiente, ou seja, quando a rotina de higienização e organização diária não estiver eliminando as pragas e seja necessário o controle químico para esta finalidade. O controle corretivo, ou controle químico de pragas deve ser feito por empresa especializada, autorizada pelo Ministério da Saúde pois esta utiliza produtos específicos. Esta empresa deve ainda fornecer um certificado do serviço prestado, onde constam os dados da empresa, os produtos que foram utilizados e a data de validade do serviço, ou seja, quando deverá ser realizado um novo controle. CONTROLE DE PRAGAS / DEDETIZAÇÃO INFORMAÇÕES GERAIS: (RDC 63/2011) Art. 63. O serviço de saúde deve garantir ações eficazes e contínuas de controle de vetores e pragas urbanas, com o objetivo de impedir a atração, o abrigo, o acesso e ou proliferação dos mesmos. Parágrafo único. O controle químico, quando for necessário, deve ser realizado por empresa habilitada e possuidora de licença sanitária e ambiental e com produtos desinfestantes regularizados pela Anvisa. Art. 64. Não é permitido comer ou guardar alimentos nos postos de trabalho destinados à execução de procedimentos de saúde</p>"}]}, {"id": "b3", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>1.PROCEDIMENTO PARA RECEBIMENTO DOS PRODUTOS ∙ Receber e conferir os produtos com a nota fiscal (validar a marca e quantidade). ∙Observar a integridade das embalagens, observando se estão com furos, sem lacres ou com vazamento ∙Se algum produto estiver violado, segregar e efetuar o procedimento de devolução ao distribuidor 2.PROCEDIMENTO PARA ARMAZENAMENTO DOS PRODUTOS ∙ Após recebimento, os produtos devem ser armazenados imediatamente no seu local apropriado. ∙ Não empilhar vidros ou litros de produtos CONTROLE DE PRAGAS / DEDETIZAÇÃO ∙ Observar se estão bem tampados e se não há vazamentos. ∙ Após utilizar produtos, guarda-los de volta no seu local apropriado ∙ Rotular e identificar bem os produtos que não estiverem em sua embalagem original 3.PROCEDIMENTO PARA MANIPULAÇÃO DE PRODUTOS Quando for necessário fazer misturas de produtos, ou retira-los de sua embalagem original: ∙ Realizar esse procedimento no local apropriado para este fim ∙ Colocar o EPI adequado. ∙ Realizar a manipulação necessária ∙ Fechar os recipientes utilizados ∙ Devolver os recipientes originais e os manipulados (caso não forem utilizados) para o local de armazenamento 4. PROCEDIMENTO PARA APLICAÇÃO DE PRODUTOS / DESINFETANTES DOMISSANITÁRIOS 4.1) Cabe a empresa controladora de vetores e pragas urbanas: ∙ Adquirir e utilizar somente produtos desinfestantes domissanitários com registro junto ao órgão competente do Ministério da Saúde ∙ Adquirir e utilizar equipamentos de aplicação de desinfestantes domissanitários adequados ao tipo de utilização e estar em perfeitas condições de uso CONTROLE DE PRAGAS / DEDETIZAÇÃO ∙ Adquirir e utilizar EPIs (Equipamentos de Proteção Individual) que atendam as regulamentações vigentes relacionadas a Saúde Ocupacional ∙ Responsabilizar-se pelo treinamento dos seus funcionários, para habilitá-los à execução das atividades de aplicação de produtos. ∙Estabelecer programa de treinamento dos aplicadores quanto procedimentos definidos pelas Normas de Segurança e quanto à correta utilização e conservação dos EPIs, bem como orientar os funcionários sobre as limitações de proteção que o EPI oferece. ∙ Manter registro dos treinamentos efetuados. ∙ Identificar a técnica de aplicação e concentração máxima especificada, atendendo as instruções do fabricante, contidas no rótulo e obedecendo a legislação pertinente Técnicas de Aplicação de produtos desinfestantes domissanitários: As atividades de aplicação de produtos desinfestantes domissanitários, devem ser realizadas somente por pessoal devidamente habilitado, considerando: ∙ Utilização de equipamento de aplicação adequado ao tipo de CONTROLE DE PRAGAS / DEDETIZAÇÃO utilização e em perfeitas condições de uso. ∙ Observação no rótulos dos produtos quanto a composição qualitativa e quantitativa do produto em questão. ∙ Manipulação e aplicação de produtos somente por pessoal devidamente treinados e portando equipamentos de proteção individual (EPI) adequados. ∙ Aplicação de produtos deverá ser supervisionada e orientada pelo Responsável Técnico. ∙Observação e cumprimento das Boas Práticas Operacionais relacionadas a: a) as condições adequadas para armazenamento/preparo dos desinfestantes domissanitários. b) métodos de aplicação, respectivos equipamentos e os cuidados para a manutenção dos mesmos. c) recomendações e cuidados prévios à aplicação, durante a execução dos serviços e após sua conclusão que visem a proteção à saúde do trabalhador e do usuário do serviço. d) procedimentos referentes ao manuseio e descarte das embalagens vazias dos desinfestantes e outros resíduos. ∙ A manipulação e aplicação de desinfestantes domissanitários de uso profissional deve ser efetuada de modo a garantir a segurança tanto dos operadores quanto dos usuários do serviço e do meio ambiente. CONTROLE DE PRAGAS / DEDETIZAÇÃO ∙ As embalagens vazias não devem se deixadas no local de aplicação, devendo retornar à empresa para a adequada destinação final. Eventuais acompanhantes dos serviços de aplicação deverão obrigatoriamente utilizar EPI’s fornecidos pela empresa</p>"}]}, {"id": "b4", "subtitulo": "REFERÊNCIAS", "linhas": [{"col1": "", "col2": "<p>RDC nº 52, de 22 de outubro de 2009 RDC Nº 63 de 25 de novembro de 2011</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '013/2026', 'Depilação', '[{"id": "b1", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever as boas práticas para a técnica de depilação</p>"}]}, {"id": "b2", "subtitulo": "EXECUTANTE", "linhas": [{"col1": "", "col2": "<p>Profissional devidamente treinado</p>"}]}, {"id": "b3", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Profissional – Luvas, óculos de proteção, touca, jaleco e máscara</p>"}]}, {"id": "b4", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<ul><li>Álcool 70%</li><li>Cremes</li><li>Talco</li><li>Cera</li><li>Pinça</li><li>Linha</li></ul>"}]}, {"id": "b5", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Protocolo</p>", "col2": "<ul><li>Desinfecção da maca com álcool 70% entre cada cliente;</li><li>Maca com lençol de papel descartável;</li><li>Higienização das mãos (ver POP de Higiene das Mãos);</li><li>Acomodar o cliente na maca durante todo o procedimento;</li><li>Higienizar a região;</li><li>Esfoliar a região, se necessário;</li><li>Realizar a técnica escolhida:</li><li>Depilação com linha: Esticar a pele para facilitar a remoção do pele e diminuir a dor; Colocar a parte da linha torcida sobre a parte do corpo que se quer remover o pelo; Abrir e fechar os dedos de apenas 1 mão, como se estivesse usando uma tesoura.</li><li>Depilação com cera: - Escolher a cera: Use uma cera de qualidade. Se a sua pele for sensível, pode optar por uma cera de algas, que é ideal para regiões delicadas. - Verificar o comprimento dos pelos: Evite pelos muito longos ou muito curtos. O comprimento ideal é de cerca de meio centímetro. - Higienizar a pele: Antes de aplicar a cera, limpe a região com água morna e sabonete neutro para remover células mortas, sujeira e outros resíduos. - Aplicar a cera: Aplique a cera na direção do crescimento dos pelos. - Remover a cera: Puxe a cera na direção contrária ao crescimento dos pelos, rente à pele, com um palito, papel próprio para depilação ou as mãos. - Remover o excesso: Remova todo o excesso de cera. - Acalmar a pele: Aplique compressas frias e um hidratante para pele irritada. - Para depilar a região íntima, esfoliar a virilha cerca de 3 dias antes para evitar pelos encravados. Deve também começar a depilação de fora para dentro e de cima para baixo. - Depois da depilação, deve jogar fora a cera e não reutilizá-la para evitar infecção. Deve também evitar a exposição ao sol por 24 horas</li></ul>"}, {"col1": "<p>B. Biossegurança</p>", "col2": "<ul><li>Maca com superfície lisa e lavável que permita higienização a cada cliente;</li><li>Lençol de papel descartável que deverá ser trocado a cada nova cliente;</li><li>Mesa auxiliar, com superfície lisa ou lavável, para a colocação dos produtos usados no ato da depilação como cremes, talco, cera e acessórios, tipo pinça;</li><li>Lixeira com saco plástico e tampa para descarte da cera e/ou linha usada. O profissional deve:</li><li>Lavar as mãos antes e depois de atender cada cliente;</li><li>Utilizar pinça descartável ou esterilizada a cada cliente;</li><li>Descartar a linha após seu uso;</li><li>Trocar o lençol descartável a cada cliente;</li><li>Utilizar cera de depilação que traga no rótulo identificação do produto, procedência, validade e número de registro na Agência Nacional de Vigilância Sanitária (ANVISA). A cera não pode ser reaproveitada por nenhum tipo de processo. Deve ser de uso único, descartada após o uso</li></ul>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '014/2026', 'Drenagem linfática', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>DRENAGEM LINFÁTICA MANUAL</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de drenagem linfática manual. A técnica de drenagem linfática manual tem como principal função potencializar os efeitos do sistema linfático corporal</p>"}]}, {"id": "b3", "subtitulo": "OBSERVAÇÃO", "linhas": [{"col1": "", "col2": "<p>A drenagem linfática pode ser coadjuvante do protocolo de tratamento para a gordura localizada. A técnica, muitas vezes, é realizada antes da aplicação de um cosmético, antes e depois da aplicação de eletroestimulação, após o procedimento da eletrolipólise ou após conduta que ocasione edema ou retenção de líquidos corporais</p>"}]}, {"id": "b4", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, PROPÉ Profissional – Touca, máscara, jaleco, óculos de proteção e luvas</p>"}]}, {"id": "b5", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>Avaliação: a. Identificar a área a ser tratada b. As mãos devem estar sempre lavadas, com unhas curtas, sem presença de anéis, pulseiras ou relógios c. Antes de iniciar a técnica, aconselha-se não tocar no cliente com as mãos frias, pode-se aquecê-las e esfregando-as uma na outra com movimentos de fricção Protocolo: Desinfecção da maca com álcool 70% Maca com lençol de papel descartável Higienização das mãos (ver Manual de Rotinas e Procedimentos) Acomodar o cliente na maca durante todo o procedimento DRENAGEM LINFÁTICA MANUAL Fazer o registro fotográfico pré-procedimento Realizar assepsia na região Aplicar o creme, se necessário Realizar os movimentos da drenagem linfática Fazer o registro fotográfico pós-procedimento B. Cuidados pós-procedimento a. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. b. Anotar na ficha do cliente todos os produtos utilizados nesse procedimento com seus respectivos números de lotes, data de validade e nome do fabricante</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>Borges, F. dos</p>"}, {"col1": "<p>S. Dermato-Funcional</p>", "col2": "<p>Modalidades terapêuticas nas disfunções estéticas</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '015/2026', 'Endermoterapia', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>ENDERMOTERAPIA</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação do procedimento de endermoterapia. Método de tratamento que utiliza equipamentos que produzem aspiração (sucção) acrescidos de uma mobilização tecidual efetuada por rolos localizados na manopla</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Lipodistrofia localizada Celulite</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Fragilidade capilar Lesões ou afecções de pele Telangectasias Microvarizes</p>"}]}, {"id": "b5", "subtitulo": "INTERVALO SUGERIDO ENTRE AS SESSÕES", "linhas": [{"col1": "", "col2": "<p>Duas a três vezes por semana</p>"}]}, {"id": "b6", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente - Touca Profissional – Touca, máscara e luvas</p>"}]}, {"id": "b7", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Algodão ou gaze Equipamento</p>"}]}, {"id": "b8", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>Avaliação: a. Identificar a área a ser tratada Protocolo: Desinfecção da maca com álcool 70% Maca com lençol de papel descartável Higienização das mãos (ver Manual de Rotinas e Procedimentos) Acomodar o cliente na maca durante todo o procedimento Fazer o registro fotográfico pré-procedimento Realizar assepsia na região Ligar o aparelho e seguir o protocolo, conforme instrução do fabricante Ajustar a pressão de sucção de acordo com a flacidez de pele pré-existente no local (geralmente está relacionado à idade do cliente ou ao emagrecimento expressivo) Realizar uma drenagem linfática após a sessão, pois a sucção pode promover edemas que mascaram os resultados do tratamento ENDERMOTERAPIA Fazer o registro fotográfico pós-procedimento B. Cuidados pós-procedimento a. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. b. Anotar na ficha do cliente todos os produtos e equipamentos utilizados nesse procedimento com seus respectivos números de lotes, data de validade e nome do fabricante</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>Borges, F. dos</p>"}, {"col1": "<p>S. Dermato-Funcional</p>", "col2": "<p>Modalidades terapêuticas nas disfunções estéticas</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '016/2026', 'Exossomas', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>nº_____ EXOSSOMAS</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever o procedimento com os exossomas. Os exossomas são vesículas extracelulares liberadas pelas células-tronco. Esses exossomas são ricos em proteínas, lipídios e ácidos nucleicos, e são conhecidos por promoverem a regeneração celular, redução da inflamação e melhora da saúde da pele</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>1. Envelhecimento cutâneo: O tratamento com exossomas pode ajudar a melhorar a textura da pele, reduzir rugas e linhas finas, e promover uma aparência mais jovem e saudável. 2. Hidratação e nutrição da pele: Os exossomas podem ajudar a melhorar a hidratação e a nutrição da pele, tornando-a mais macia, suave e radiante. 3. Redução de manchas e pigmentação: Evidências sugerem que os exossomas podem ajudar a reduzir a pigmentação irregular e manchas na pele, proporcionando um tom mais uniforme. 4. Cicatrização de feridas: Em algumas situações, o tratamento com exossomas pode ser utilizado para auxiliar na cicatrização de feridas e lesões cutâneas. 5. Melhora da saúde da pele: Para pessoas com diversos problemas de pele, como acne, rosácea, eczema, entre outros, o tratamento com exossomas pode ser uma opção para melhorar a saúde geral da pele</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>1. Gravidez e amamentação: Mulheres grávidas ou lactantes geralmente são desencorajadas a realizar tratamentos estéticos que envolvam produtos ou procedimentos invasivos, incluindo o tratamento com exossomas, devido aos possíveis riscos para o feto ou para o bebê. 2. Infecções ativas: Pacientes com infecções ativas na área a ser tratada devem adiar o tratamento até que a infecção seja resolvida, para evitar complicações ou disseminação da infecção. 3. Histórico de alergias: Indivíduos com histórico conhecido de alergias a qualquer um dos componentes dos exossomas ou a outros produtos utilizados durante o tratamento devem evitar o procedimento para evitar reações alérgicas adversas. 4. Lesões cutâneas abertas: Lesões cutâneas abertas, feridas ou úlceras na área a ser tratada devem ser completamente cicatrizadas antes de realizar o tratamento com exossomas, para evitar infecções ou irritações adicionais. 5. Condições médicas específicas: Pacientes com condições médicas graves, como câncer de pele ou doenças autoimunes, devem consultar seus médicos antes de realizar tratamentos estéticos, incluindo o tratamento com exossomas, devido ao risco de complicações ou interações com sua condição médica</p>"}]}, {"id": "b5", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Profissional – Touca, jaleco, óculos de proteção, máscara e luvas nº_____ EXOSSOMAS</p>"}]}, {"id": "b6", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>O tratamento com exossomas geralmente envolve o uso de produtos específicos que contêm exossomas em sua formulação, bem como outros materiais e equipamentos para aplicação. 1. Produtos contendo exossomas: São produtos desenvolvidos para a aplicação tópica na pele e contêm exossomas em sua formulação. Esses produtos podem ser séruns, cremes, máscaras faciais ou outros tipos de produtos cosméticos. Eles geralmente são formulados para penetrar na pele e liberar os exossomas, proporcionando os benefícios desejados, como regeneração celular, redução da inflamação e melhora da saúde da pele. 2. Microagulhas ou dermaroller: Em alguns casos, o tratamento com exossomas pode envolver a utilização de microagulhas ou dermaroller para facilitar a absorção dos exossomas na pele. Esses dispositivos criam microperfurações na pele, permitindo que os produtos aplicados penetrem mais profundamente. 3. Máquinas de microdermoabrasão: Em procedimentos que visam uma esfoliação mais profunda da pele, máquinas de microdermoabrasão podem ser utilizadas para remover as camadas superficiais de células mortas da pele e preparar a pele para a aplicação dos exossomas. 4. Equipamento de LED ou terapia de luz: Em alguns casos, a aplicação de exossomas pode ser combinada com terapia de luz LED para potencializar os resultados do tratamento. A luz LED pode ajudar a melhorar a circulação sanguínea, reduzir a inflamação e estimular a produção de colágeno na pele. 5. Equipamentos de aplicação tópica: Dependendo da forma de aplicação dos exossomas (como seringas, aerossóis ou dispositivos de pulverização), podem ser necessários equipamentos específicos para aplicar os produtos de maneira eficaz na pele. 6. Produtos de limpeza e preparação da pele: Antes da aplicação dos exossomas, a pele geralmente é limpa e preparada para garantir a eficácia do tratamento. Isso pode envolver o uso de produtos de limpeza facial, tônicos adstringentes ou outros produtos de preparação da pele. 7. Protetor solar: Após o tratamento com exossomas, é importante proteger a pele da exposição solar excessiva, então o uso de protetor solar é frequentemente recomendado como parte dos cuidados pós-tratamento</p>"}]}, {"id": "b7", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Anamnese</p>", "col2": "<p>Avaliação inicial: Antes de iniciar qualquer tratamento, é essencial realizar uma avaliação inicial do paciente para entender suas necessidades específicas, histórico médico, condições da pele e expectativas em relação ao tratamento com exossomas. B. Procedimento 1. Preparação da pele: Limpeza profunda da pele para remover sujeira, óleo e resíduos de maquiagem. Isso pode incluir técnicas como limpeza com ácido salicílico, vaporização facial ou microdermoabrasão, dependendo das necessidades da pele do paciente. 2. Aplicação dos exossomas: Os exossomas podem ser administrados na pele de várias maneiras, como por meio de microagulhamento, aplicação tópica ou injeções intradérmicas. A forma de aplicação dependerá das preferências do paciente, da nº_____ EXOSSOMAS área a ser tratada e das recomendações do profissional de estética. 3. Protocolo de tratamento: O número de sessões e a frequência do tratamento variam de acordo com as necessidades individuais do paciente e a gravidade das preocupações com a pele. O profissional irá elaborar um protocolo de tratamento personalizado com base na avaliação inicial: 3.1 Microagulhamento + Exossomas: O microagulhamento é um procedimento que envolve o uso de um dispositivo com pequenas agulhas para criar microperfurações na pele. Esse procedimento pode ser combinado com a aplicação de exossomas para facilitar sua absorção na pele, promovendo a regeneração celular e a produção de colágeno. Essa combinação é eficaz para melhorar a textura da pele, reduzir rugas e linhas finas e tratar cicatrizes de acne. 3.2 Peeling químico + Exossomas: Os peelings químicos são tratamentos que envolvem a aplicação de ácidos na pele para remover as camadas superficiais e promover a renovação celular. A combinação de peelings químicos com a aplicação de exossomas pode ajudar a maximizar os resultados do tratamento, promovendo uma pele mais suave, brilhante e uniforme, ao mesmo tempo em que reduz a inflamação e melhora a saúde geral da pele. 3.3 Terapia de luz LED + Exossomas: A terapia de luz LED utiliza diferentes comprimentos de onda de luz para tratar uma variedade de preocupações de pele, como acne, rosácea, hiperpigmentação e envelhecimento cutâneo. A combinação da terapia de luz LED com a aplicação de exossomas pode potencializar os resultados do tratamento, estimulando a regeneração celular, reduzindo a inflamação e promovendo uma pele mais saudável e radiante. 3.4 Tratamentos a laser + Exossomas: Os tratamentos a laser são utilizados para uma variedade de preocupações de pele, incluindo remoção de pelos, tratamento de manchas e lesões pigmentadas, melhora da textura da pele e redução de rugas e linhas finas. A combinação de tratamentos a laser com a aplicação de exossomas pode ajudar a acelerar a cicatrização da pele, reduzir o tempo de recuperação e melhorar os resultados globais do tratamento. 3.5 Máscaras faciais + Exossomas: As máscaras faciais são uma maneira popular de fornecer ingredientes ativos à pele de forma concentrada. As máscaras faciais contendo exossomas podem oferecer benefícios adicionais, como hidratação profunda, nutrição da pele e melhora da elasticidade e firmeza da pele. 3.6 Tratamento capilar com exossomas: nº_____ EXOSSOMAS O tratamento capilar com exossomas é uma técnica que pode ajudar a melhorar a saúde do couro cabeludo e dos fios, promovendo o crescimento capilar, reduzindo a queda e melhorando a aparência geral do cabelo. Avaliação inicial:</p><ul><li>Antes de iniciar o tratamento, é importante realizar uma avaliação do couro cabeludo e dos fios para identificar quaisquer problemas específicos, como queda de cabelo, quebra, caspa ou couro cabeludo seco. Limpeza do couro cabeludo:</li><li>Comece o tratamento com uma limpeza suave do couro cabeludo para remover qualquer acúmulo de produtos capilares, oleosidade e sujeira. Use um shampoo suave e massageie suavemente o couro cabeludo com as pontas dos dedos. Enxágue completamente com água morna. Preparação do produto com exossomas:</li><li>Prepare o produto contendo exossomas de acordo com as instruções do fabricante. Isso pode envolver agitar bem o produto ou misturá-lo com outros ingredientes, se necessário. Aplicação do produto com exossomas:</li><li>Aplique o produto com exossomas diretamente no couro cabeludo e ao longo do comprimento dos fios. Divida o cabelo em seções para garantir uma aplicação uniforme. Massageie suavemente o couro cabeludo durante a aplicação para promover a absorção do produto. Tempo de espera:</li><li>Deixe o produto com exossomas agir no cabelo e couro cabeludo pelo tempo recomendado pelo fabricante. Isso pode variar de alguns minutos a uma hora, dependendo do produto e das necessidades individuais do cabelo. Enxágue:</li><li>Após o tempo de espera, enxágue completamente o cabelo com água morna para remover o produto. Certifique-se de enxaguar completamente para evitar deixar resíduos no cabelo. Cuidados adicionais:</li><li>Se desejar, você pode seguir o tratamento com exossomas com um condicionador hidratante ou máscara capilar para proporcionar hidratação adicional aos fios. Secagem e estilização:</li><li>Seque o cabelo suavemente com uma toalha, evitando esfregar vigorosamente, o que pode causar danos aos fios. Em seguida, você pode estilizar o cabelo conforme desejar, usando ferramentas de calor com moderação para evitar danos adicionais. Manutenção:</li><li>Dependendo das necessidades do cabelo, o tratamento com exossomas pode ser repetido regularmente para manter os resultados. Siga as orientações do profissional de estética ou do fabricante do produto para determinar a frequência adequada do tratamento. nº_____ EXOSSOMAS</li></ul>"}, {"col1": "<p>C. Cuidados pós-procedimento</p>", "col2": "<p>I. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. II. Entregar uma via do Termo para o cliente. III. Após o procedimento, é importante fornecer orientações de cuidados pós-tratamento ao paciente. Isso pode incluir o uso de protetor solar, evitando a exposição prolongada ao sol, utilizando produtos de cuidados da pele suaves e hidratantes, entre outras recomendações. IV. Durante todo o processo, é fundamental educar o paciente sobre os benefícios do tratamento com exossomas, o que esperar durante o procedimento e os cuidados necessários após o tratamento para otimizar os resultados</p>"}, {"col1": "<p>D. Referências literárias</p>", "col2": "<p>Apostila do Curso de Exossomas (inserir aqui o nome do curso e o nome do profissional que você fez o curso de bioestimuladores) David</p>"}, {"col1": "<p>W. Greening e</p>", "col2": "<p>Richard J. Simpson. Exosomes: From Biogenesis and Secretion to Biological Function (livro). Clotilde Théry et al. Extracellular Vesicles: Exosomes, Microvesicles, and Friends. The Journal of Cell Biology. Lixia Qiao e Zhanfeng Cui. Extracellular Vesicles: Potential Roles in Regenerative Medicine</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '017/2026', 'Fios Absorvíveis', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>FIOS ABSORVÍVEIS (PDO)</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação do procedimento de Fios Absorvíveis de PDO (polidioxanona). Trata-se de um procedimento de lifting facial (ou corporal) não-cirúrgico com aplicação de fio PDO através de finas agulhas (de acupuntura)</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Rugas Flacidez facial e corporal</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Infecção na região de tratamento Doenças autoimunitárias ativas Gravidez e lactação Diabetes grave não-controlada Doença cardiovascular aguda</p>"}]}, {"id": "b5", "subtitulo": "OBSERVAÇÃO", "linhas": [{"col1": "", "col2": "<p>Os fios PDO começam a atuar imediatamente, a partir da terceira semana os efeitos reais começam a ser visíveis e o ponto de efeito máximo é atingido após 2 a 3 meses. Os efeitos estéticos deste procedimento perduram por até 36 meses em média</p>"}]}, {"id": "b6", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente - Touca Profissional – Touca, máscara e luvas</p>"}]}, {"id": "b7", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Álcool 70% Algodão ou gaze Agulha Fios</p>"}]}, {"id": "b8", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "", "col2": "<p>A. Procedimento 1. Anamnese (tirar foto da área a ser tratada) 2. Identificar a região a ser tratada Protocolo: Anestesia tópica 30-40 minutos antes da aplicação Desinfecção da maca com álcool 70% Maca com lençol de papel descartável Higienização das mãos (ver Manual de Rotinas e Procedimentos) Acomodar o cliente na maca durante todo o procedimento Fazer o registro fotográfico pré-procedimento Escolher o fio Fazer a marcação na área a ser tratada Realizar assepsia na região Introduzir o fio escolhido Fazer o registro fotográfico pós-procedimento - Tipos de Fios: a. Fio duplo enrolado na agulha b. Fio duplo enrolado no seu eixo c. Fio simples d. Fio de tração mecânica com garras FIOS ABSORVÍVEIS (PDO) e. Fio especial com cânula especial</p>"}, {"col1": "<p>B. Cuidados pós-procedimento</p>", "col2": "<p>Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>Procedimentos Estéticos Minimamente Invasivos, Charles Yamaguchi, Grupo</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '018/2026', 'Fototerapia e LED', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>FOTOTERAPIA E LED</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação do procedimento de fototerapia e LED. Caracteriza-se por um procedimento não-invasivo baseado na bioestimulação ou bioinibição da atividade celular</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<ul><li>Rejuvenescimento</li><li>Acne</li><li>Alopécias/ Tratamento capilar</li><li>Pós-operatórios</li><li>Discromias</li><li>Manchas</li><li>Efeito bactericida e Antifúngico</li><li>Onicomicoses</li><li>Cicatrização de Feridas</li><li>Queimaduras</li><li>Reparação tecidual</li><li>Dermatites</li><li>Psoriase</li><li>Dermatite Atópica</li><li>Vitiligo</li><li>Analgesia</li><li>Terapia Fotodinâmica</li><li>Rosácea</li></ul>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<ul><li>Gestantes</li><li>Epilepsia</li><li>Câncer de pele</li><li>Neoplasias em atividade</li><li>Hipersensibilidade cutânea</li><li>Epilepsia (modo pulsado)</li><li>Irradiação no globo ocular (ceratites)</li><li>Lúpus eritematoso</li><li>Eczema fotossensível</li><li>Uso de medicamento fotossensibilizante</li><li>Tumor de pele não tratado FOTOTERAPIA E LED</li></ul>"}]}, {"id": "b5", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, óculos de proteção Profissional – Touca, jaleco, óculos de proteção, máscara e luvas LEDs: A sigla leds vem do inglês que quer dizer Light Emitting Diode, são diodos semicondutores envoltos por um encapsulamento translúcido, sendo que estes, quando submetidos uma corrente elétrica emitem luz. Os Leds possuem um papel diferente do tratamento ablativo, pois não causam dano tecidual baseado na fototermólise, pelo contrário, sua ação se dá através da estimulação direta intracelular mais especificamente nas mitocôndrias, reorganizando as células, inibindo ações e estimulando outras, resultando no efeito da fotobioestimulação ou fotobiomodulação. Estimula assim a síntese de ATP e consequentemente as proteínas, como o colágeno e elastina, contribuindo também para a divisão celular, bem como inibindo a colagenase. A luz Azul (470nm) tem grande utilização no tratamento da acne, na qual produzem pigmentos fluorescentes chamadas de porfirina e esta luz atua nessa porfirinas causando um stress oxidativo que induz a apoptose das células afetadas. Já a luz Vermelha (630nm) atua modulando a energia celular, aumentando a produção de ATP (adenosina trifosfato) com consequente aumento na produção de colágeno e elastina. Melhora também a circulação local e o metabolismo, estimula o reparo tecidual (cicatrização) e também tem ação anti-inflamatória. O comprimento de onda azul atua como bactericida, as bactérias causadoras de acne produzem pigmentos fluorescentes chamadas de porfirina e esta luz atua nessa porfirinas causando um stress oxidativo que induz a apoptose das células afetadas. O comprimento de onda vermelho estimula os fibroblastos, aumenta a síntese do colágeno, diminui a ação da enzima colagenase e acelera a degradação dos mastócitos entre outros efeitos secundários. O comprimento de FOTOTERAPIA E LED onda infravermelho produz uma algesia pelo efeito térmico e pelo aumento do metabolismo além de inibição dos nociceptores de dor. MEDIDAS DE SEGURANÇA: Realizar e registrar treinamento da técnica no profissional que realizará o procedimento, conforme modelo disponível abaixo no ANEXO I A proteção dos olhos é imprescindível. Os fabricantes já disponibilizam os óculos juntamente com o equipamento, e devem ser utilizados pelo cliente e pelo profissional que está realizando o procedimento</p>"}]}, {"id": "b6", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>Equipamento</p>"}]}, {"id": "b7", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "<p>A. Procedimento</p>", "col2": "<p>Avaliação: a. Realizar a anamnese e verificar os critérios de exclusão do tratamento b. Identificar a área a ser tratada Protocolo: 1. Desinfecção da maca com álcool 70% 2. Maca com lençol de papel descartável 3. Higienização das mãos (ver Manual de Rotinas e Procedimentos) 4. Acomodar o cliente na maca durante todo o procedimento 5. Fazer o registro fotográfico pré-procedimento 6. A região a ser tratada deve estar limpa e seca, sem uso de hidratantes, óleos, desodorantes, ou seja, livre de todo e qualquer produto. 7. Colocar o Protetor intraocular 8. Aplicar a técnica conforme Manual de Instrução do fabricante do equipamento. FOTOTERAPIA E LED 9. Fazer o registro fotográfico pós-procedimento B. Cuidados pós-procedimento a. Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. b. Anotar na ficha do cliente todos os produtos e equipamentos utilizados nesse procedimento com seus respectivos números de lotes, data de validade, número de registro na Anvisa e nome do fabricante</p>"}, {"col1": "<p>C. Referências literárias</p>", "col2": "<p>Manual do Equipamento Hygialux (BCMED)</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '019/2026', 'HIALURONIDASE', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>nº___________ HIALURONIDASE</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de aplicação da enzima de hialuronidase. A enzima de hialuronidase é um produto capaz de reverter preenchimentos faciais à base de ácido hialurônico (AH). A hialuronidase é uma enzima que, quando injetada na região da pele que recebeu o ácido hialurônico, “quebra” essa substância, revertendo seus efeitos. A hialuronidase é uma enzima que atua na despolimerização do AH, quebrando as ligações entre os resíduos N-acetil-D-glucosamina e ácido D-glucurônico, reduzindo a massa molar e viscosidade do ácido, transformando sua viscoelasticidade, e, dessa forma, retomando o fluxo sanguíneo local</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>O uso da enzima hialuronidase, é indicado para minimizar as possíveis intercorrências advindas do excesso de material no preenchimento estético, ou quando a aplicação do AH é feita inadequadamente fora do local planejado</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Pacientes com hipersensibilidade aos componentes da fórmula. Em gestantes, a hialuronidase é considerada categoria de risco C (onde não existem estudos controlados em humanos). Um teste cutâneo pode ser feito antes da utilização do material no paciente para verificar se existe ou não alguma reação alérgica. Para hialuronidase a execução deste teste preliminar é recomendada pelas bulas dos medicamentos, de forma que o uso é contraindicado nos resultados positivos. Para execução do teste, são aplicadas 15 a 30 UTRS no antebraço, em forma de pápula, na área delimitada de 2cm de diâmetro. Aguarde 30 minutos, se observar calor e formação de pápula eritematosa no local, indica a positividade do teste. Para alguns autores, a execução desse teste não se faz necessária, pois, a presença de complicações alérgicas são muito raras e podem ocorrer mesmo que o teste cutâneo seja negativo. Não realizar o teste alérgico na presença de um evento vascular. TIPOS DE HIALURONIDASE: A hialuronidase para o uso clínico, podem ser de origem animal ou recombinante humana. No Brasil, a apresentação farmacêutica mais comumente utilizada da hialuronidase, foi a Hyalozima (fabricante: Apsen Farmacêutica S.A.), cujo registro na Agência Brasileira de Vigilância Sanitária (ANVISA) está vencido desde o ano de 2017. INTERAÇÕES MEDICAMENTOSAS: Alguns fármacos como corticosteroides, estrógenos, salicilatos, hormônio adrenocorticotrófico e anti-histamínicos, presumem fazer com que os tecidos fiquem parcialmente resistentes à degradação do AH pela hialuronidase. nº___________ HIALURONIDASE Benzodiazepínicos, furosemida e fenitoína, aparentam incompatibilidade com a hialuronidase</p>"}]}, {"id": "b5", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, propé Profissional – Touca, jaleco, máscara, óculos de proteção e luvas</p>"}]}, {"id": "b6", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<ul><li>Diluente</li><li>Enzima</li><li>Álcool 70%</li><li>Algodão ou gaze</li><li>Cânula</li><li>Agulha</li><li>Seringa</li><li>Anestésico</li></ul>"}]}, {"id": "b7", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "", "col2": "<p>A. Procedimento 1. Anamnese (tirar foto da área a ser tratada) 2. Identificar a região a ser tratada (glabela, frontal, periorbital, pescoço, etc) Protocolo:</p><ul><li>Caso houver necessidade de anestesia prévia, não utilizar anestésico com vasoconstritor</li><li>Desinfecção da maca com álcool 70%</li><li>Maca com lençol de papel descartável</li><li>Higienização das mãos (ver Manual de Rotinas e Procedimentos)</li><li>Acomodar o cliente sentado na maca durante todo o procedimento</li><li>Fazer o registro fotográfico pré-procedimento</li><li>Remover a quantidade necessária de diluente para fazer o preparo da hialuronidase</li><li>Dispensar o diluente já removido dentro da empola que contem a enzima</li><li>Aspirar a mistura pronta para uso em seringa de aplicação Sugestão de preparo para Tratamentos Estéticos para enzimas de 2000 UTRS: Coloque 2mL do diluente dentro do frasco com a enzima. Com isso, você terá 1000 UTR/mL. Com a seringa BD de 50 unidades, puxe 0,5mL (toda a seringa)</li></ul>"}]}, {"id": "b8", "subtitulo": "OBSERVAÇÃO", "linhas": [{"col1": "", "col2": "<p>1 traço da seringa de 50 vai representar 10 UTRS 50 UN = 500 UTRS (diluição sugerida) Sugestão de uso para risco ou presença de necrose em Nariz e Lábios: Diluir utilizando a proporção de 5mL para 2000 UTRS Aplicar a quantidade total em toda área afetada Repetir o procedimento a cada 20 minutos com a mesma quantidade e diluição nº___________ HIALURONIDASE Sugestão de uso para risco ou presença de necrose em Outras Áreas: Diluir utilizando a proporção de 1mLmL para 1000 UTRS Aplicar a quantidade de 2000 UTRS em toda área afetada Repetir o procedimento a cada 20 minutos com a mesma quantidade e diluição</p><ul><li>Fazer o registro fotográfico pós-procedimento</li><li>Descartar o produto como lixo perfurocortante (recipiente rígido, conforme Manual de Rotinas e Procedimentos)</li></ul>"}, {"col1": "<p>B. Cuidados pós-procedimento</p>", "col2": "<p>Anexar na ficha do paciente/cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente</p>"}, {"col1": "<p>C. Referência literária</p>", "col2": "<p>A evolução do protocolo de utilização da hialuronidase. Revista FACE. Out, 2021</p>"}]}]'::jsonb),
  ((select id from clinics order by created_at limit 1), '020/2026', 'Hidratação e Regeneração Labial', '[{"id": "b1", "subtitulo": "DESCRIÇÃO", "linhas": [{"col1": "", "col2": "<p>HIDRATAÇÃO E REGENERAÇÃO LABIAL</p>"}]}, {"id": "b2", "subtitulo": "OBJETIVO", "linhas": [{"col1": "", "col2": "<p>Descrever a técnica de hidratação e regeneração labial, também conhecida como “Hydra Gloss”. Trata-se de um procedimento feito através de um dispositivo eletrônico, chamado de “dermapen” ou “microagulhamento elétrico”, que se assemelha a uma caneta, em que um jogo de agulhas descartáveis é colocado na extremidade da caneta. O microagulhamento ocasiona micro lesões nos lábios, promovendo a permeação de ativos, proporcionando alta hidratação e estímulo do colágeno</p>"}]}, {"id": "b3", "subtitulo": "PRINCIPAIS INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Hidratação, regeneração labial e volumização das linhas finas de expressão</p>"}]}, {"id": "b4", "subtitulo": "PRINCIPAIS CONTRA-INDICAÇÕES", "linhas": [{"col1": "", "col2": "<p>Herpes ativa Alergia ao metal ou ao produto Uso de anticoagulantes Gravidez Processo inflamatório / infecção de pele</p>"}]}, {"id": "b5", "subtitulo": "INTERVALO SUGERIDO ENTRE AS SESSÕES", "linhas": [{"col1": "", "col2": "<p>O tratamento é dividido em três sessões com intervalo entre as sessões de uma semana a dez dias, de acordo com o estabelecido pelo profissional</p>"}]}, {"id": "b6", "subtitulo": "EQUIPAMENTO DE PROTEÇÃO INDIVIDUAL (EPI)", "linhas": [{"col1": "", "col2": "<p>Cliente – Touca, propé Profissional – Touca, jaleco, máscara e luvas</p>"}]}, {"id": "b7", "subtitulo": "MATERIAIS", "linhas": [{"col1": "", "col2": "<p>1.Álcool 70% 2.Algodão ou gaze 3.Dispositivo eletrônico (caneta dermapen): A caneta é posicionada em 90° em relação com a pele e o movimento realizado pelo profissional é de arraste ou pontual, dependendo da profundidade da agulha. A caneta conta com diferentes velocidades que variam de acordo com a sensibilidade do cliente e do objetivo a ser atingido</p>"}]}, {"id": "b8", "subtitulo": "PASSO A PASSO", "linhas": [{"col1": "", "col2": "<p>A. Procedimento 1. Anamnese (tirar foto da área a ser tratada) 2. Definir o número de sessões e intervalos entre as sessões Protocolo: 1. Desinfecção da maca com álcool 70% 2. Maca com lençol de papel descartável 3. Higienização das mãos (ver Manual de Rotinas e Procedimentos) 4. Acomodar o cliente na maca durante todo o procedimento 5. Fazer o registro fotográfico pré-procedimento 6. Aplicar anestésico (deixar agir por 20-30 minutos) 7. Retirar o anestésico 8. Realizar assepsia na região 9. Realizar a esfoliação 10. Aplicar a técnica HIDRATAÇÃO E REGENERAÇÃO LABIAL a. Realizar a técnica com o auxílio da caneta, conforme manual do fabricante</p>"}]}, {"id": "b9", "subtitulo": "ATENÇÃO", "linhas": [{"col1": "", "col2": "<p>Acima de 1,5mm (ou até menos, dependendo do caso) o movimento passa a ser pontual e não de arraste. O movimento de arraste com agulhas mais profundas pode gerar lesão maior e até cicatriz na pele. 11. Aplicar os produtos (ácido hialurônico e hidratantes) conforme disfunção estética 12. Finalizar com máscara lip patch para absorção total dos ativos 13. Fazer o registro fotográfico pós-procedimento 14. Descartar as agulhas da caneta como lixo perfurocortante (recipiente rígido, conforme Manual de Rotinas e Procedimentos e PGRSS)</p>"}, {"col1": "<p>B. Cuidados pós-procedimento</p>", "col2": "<p>Anexar na ficha do cliente uma via do Termo de Consentimento com os cuidados pós-procedimento assinado pelo próprio cliente. Entregar uma via do Termo para o cliente. A manutenção poderá ser realizada pelo próprio cliente em casa utilizando o frasco de “Hydra Gloss Home Care”</p>"}, {"col1": "<p>C. Referência literária</p>", "col2": "<p>Terapêutica em Estética, Conceitos e Técnicas, Fábio Borges e Flávia Scorza, Editora Phorte, 2016 Manual de Instrução do equipamento Dermapen Smart</p>"}]}]'::jsonb)
